local config = {
  ui_story_5022_50220101_1_dialog_content = "Nng... Vice...",
  ui_story_5022_50220101_2_dialog_content = "Vice... I need you here...",
  ui_story_5022_50220101_3_dialog_content = "(If only I apologized to her back then...)",
  ui_story_5022_50220101_4_dialog_content = "<color=#e8d9bb>A few days ago...</color>",
  ui_story_5022_50220101_5_dialog_content = "<size=45>Take this!</size>",
  ui_story_5022_50220101_6_dialog_content = "Whoa, when did you...?! Damn, what kind of cornering technique is that?!",
  ui_story_5022_50220101_7_dialog_content = "Heh, I still have plenty more up my sleeve! We're halfway to the finish line now... This race is as good as mine!",
  ui_story_5022_50220101_8_dialog_content = "I gotta admit that you're good at racing games, but it's still way too early for you to be celebrating!",
  ui_story_5022_50220101_9_dialog_content = "Right! Time to show you the Rediesel Wrench's secret racing technique—",
  ui_story_5022_50220101_10_dialog_content = "...Hey!",
  ui_story_5022_50220101_11_dialog_content = "V-Vice? Why'd you turned the terminal off?! I was just about to win, too...",
  ui_story_5022_50220101_12_dialog_content = "Do you really need me to explain?",
  ui_story_5022_50220101_13_dialog_content = "Setting aside the fact that you're playing with the Colossus' training programs like they're video games... Have you completely forgotten about this list?!",
  ui_story_5022_50220101_14_dialog_content = "What list? Let me take a look... \"Self-training Regiment\"?",
  ui_story_5022_50220101_15_dialog_content = "\"Mornings: 100 push-ups. Afternoons: 100 sit-ups. Evenings: 100 squats. Daily long-distance runs...\"",
  ui_story_5022_50220101_16_dialog_content = "Holy smokes, that's an ambitious plan you've got there, kid...",
  ui_story_5022_50220101_17_dialog_content = "Now tell me, PlayerName, how many of these have you actually done?",
  ui_story_5022_50220101_18_dialog_content = "Uh... W-Well, I did do sit-ups this afternoon! I mean, technically I was lying down for a long time and sat up once, but...",
  ui_story_5022_50220101_19_dialog_content = "Getting up from your afternoon nap doesn't count!!",
  ui_story_5022_50220101_20_dialog_content = "You made such an ambitious plan for yourself, but every time I check on you, it's nothing but games, games, and more games...",
  ui_story_5022_50220101_21_dialog_content = "Morning to night, that's all you've been doing lately!",
  ui_story_5022_50220101_22_dialog_content = "Y-Yeah, but... Video games are like training if you think about it! My hands are firm now, and my reflexes have never been better!",
  ui_story_5022_50220101_23_dialog_content = "Right, Sinsa?",
  ui_story_5022_50220101_24_dialog_content = "R-Right! That cornering technique just now was insane!",
  ui_story_5022_50220101_25_dialog_content = "Ugh... You know what?",
  ui_story_5022_50220101_26_dialog_content = "You can forget about me ever helping you with anything again! From now on, you're on your own!",
  ui_story_5022_50220101_27_dialog_content = "I'm done for... What am I supposed to do if she's not there to remind me about my duties? I can be really forgetful about stuff sometimes!",
  ui_story_5022_50220101_28_dialog_content = "Who on earth even came up with such a crazy workout plan?!",
  ui_story_5022_50220101_29_dialog_content = "... Alright, yeah, it was me.",
  ui_story_5022_50220101_30_dialog_content = "I wonder if it's too late to apologize?",
  ui_story_5022_50220101_31_dialog_content = "What if she tries to make me finish all of my workouts for the day as my punishment?",
  ui_story_5022_50220101_32_dialog_content = "I'd be a goner, that's for sure...",
  ui_story_5022_50220101_33_dialog_content = "Yeah, no kidding.",
  ui_story_5022_50220101_34_dialog_content = "Look, Vice is really ticked off right now. Why not wait until she cools off a bit before trying to make amends? Who knows? She might even let you off the hook entirely!",
  ui_story_5022_50220101_35_dialog_content = "You have a point... Wait, why do you seem so familiar with this kind of thing?",
  ui_story_5022_50220101_36_dialog_content = "Heh, having a little sister teaches you a thing or two... Anyway, for the time being, try not to show your face around her.",
  ui_story_5022_50220101_37_dialog_content = "But we're on the Colossus... Where am I supposed to go?",
  ui_story_5022_50220101_38_dialog_content = "Hang on, I just remembered! It's almost that time of the year!",
  ui_story_5022_50220101_39_dialog_content = "Hey, PlayerName... Wanna see what a real race looks like?",
  ui_story_5022_50220101_40_dialog_content = "I never expected to see something like this in the desert... What is this place?",
  ui_story_5022_50220101_41_dialog_content = "Welcome to <color=#FFB400>Oasis</color>, one of the Rediesel Wrench's main strongholds!",
  ui_story_5022_50220101_42_dialog_content = "The visibility around here is pretty bad, right? Even with Lepidoz, we couldn't see more than two meters out because of all the sand and wind... Which is exactly what we want.",
  ui_story_5022_50220101_43_dialog_content = "The terrain around here is pretty complex, and the weather is just as unpredictable. We're the only ones who know how to find this place.",
  ui_story_5022_50220101_44_dialog_content = "Well, to be fair, we have a hard time finding it sometimes, too...",
  ui_story_5022_50220101_45_dialog_content = "\"Oasis\"...",
  ui_story_5022_50220101_46_dialog_content = "See that workshop over there? We repair our vehicles and weapons there when a good whack or two doesn't fix'em anymore.",
  ui_story_5022_50220101_47_dialog_content = "And that treehouse over there is perfect for getting a good night's sleep. The walls keep the sand from getting into your clothes, but the whole place tends to rock back and forth when the wind's particularly strong.",
  ui_story_5022_50220101_48_dialog_content = "You can buy sandy date cakes from this place, and their red scorpion pie is pretty decent.",
  ui_story_5022_50220101_49_dialog_content = "And only twenty or thirty people get sick every month from eating them! That's as safe as it gets! You can try your luck too, if you want? Oh, and over there...",
  ui_story_5022_50220101_50_dialog_content = "Hey, Sinsa! Welcome back!",
  ui_story_5022_50220101_51_dialog_content = "We've just unloaded the latest goods from the giant lizard.",
  ui_story_5022_50220101_52_dialog_content = "I hear Azure's the one who led the way this time. Not a bad haul!",
  ui_story_5022_50220101_53_dialog_content = "We're on our way to deliver it to the warehouse, now that they've finished taking stock of it. Care to take a look, Sinsa?",
  ui_story_5022_50220101_54_dialog_content = "Nah, you can leave all that number stuff to Roy. Speaking of, have you guys seen him around?",
  ui_story_5022_50220101_55_dialog_content = "—O, mighty adventurer from a distant land! I can see the burden of destiny weighs heavily upon your shoulders...",
  ui_story_5022_50220101_56_dialog_content = "Are you in need of the wind's guidance, as well?",
  ui_story_5022_50220101_57_dialog_content = "Adventurer...?",
  ui_story_5022_50220101_58_dialog_content = "Hey, Zeta! It's been a while, huh? Still playing make-believe, I see!",
  ui_story_5022_50220101_59_dialog_content = "M... Make-believe...?!",
  ui_story_5022_50220101_60_dialog_content = "Ah, I see now...",
  ui_story_5022_50220101_61_dialog_content = "After the cruel hand of fate forced us to part ways, the backlash from the evil god's power caused you to lose your memories and forget your destiny...",
  ui_story_5022_50220101_62_dialog_content = "But worry not, for I am here. There is nothing to fear now.",
  ui_story_5022_50220101_63_dialog_content = "Awaken, o cursed warrior! Awaken, ye lonely and thrice-divorced berserker, doomed to roam the lands with no place to call home!",
  ui_story_5022_50220101_64_dialog_content = "Huh...? Oh yeah, I guess some of that makes sense...",
  ui_story_5022_50220101_65_option_content = "\"Cursed warrior\"?",
  ui_story_5022_50220101_66_dialog_content = "Ah, it's just part of Zeta's make-believe game. She made up an entire persona just for me.",
  ui_story_5022_50220101_67_dialog_content = "Now, how did it go...? I was roaming the land in search of power, and then... something about my soul...",
  ui_story_5022_50220101_68_dialog_content = "You went to the ruins of Ishradi and offered your soul to the ancient god of evil, Y'noth-raz!",
  ui_story_5022_50220101_69_option_content = "You've been divorced three times already?",
  ui_story_5022_50220101_70_dialog_content = "\"Hell no!\"",
  ui_story_5022_50220101_71_dialog_content = "It's all a part of, uh... What's it called? ...Oh yeah! A \"role-playing game\"! Zeta made up an entire character just for me.",
  ui_story_5022_50220101_72_dialog_content = "Thing is, she keeps changing up parts of the story, so I'm not really sure where we are right now...",
  ui_story_5022_50220101_73_dialog_content = "You were roaming the land in search of greater power, and after arriving at the ruins of Ishradi, you offered your soul to the ancient god of evil, Y'noth-raz!",
  ui_story_5022_50220101_74_dialog_content = "But soon after, you realized that it was a cursed power, and so... You began your journey to defeat the demon king...",
  ui_story_5022_50220101_75_dialog_content = "Oh, yeah! I remember now!",
  ui_story_5022_50220101_76_dialog_content = "Thank goodness you've come to your senses. Now, o mighty berserker, may I kindly ask... Who is that next to you?",
  ui_story_5022_50220101_77_option_content = "N-Nice to meet you! My name is PlayerName!",
  ui_story_5022_50220101_78_dialog_content = "PlayerName, you say? Hmm... I can sense an ancient and mysterious power lying dormant deep within you...",
  ui_story_5022_50220101_79_dialog_content = "Could be because I'm a Caelestite... Have you heard of us? A race of people who can see Lumina, as well as pilot the great Colossi!",
  ui_story_5022_50220101_80_option_content = "I am the last of the Caelestites! The Navigator of the Colossus, and the guide of light!",
  ui_story_5022_50220101_81_dialog_content = "<size=45>The... The Last of the Caelestites!!!</size>",
  ui_story_5022_50220101_82_dialog_content = "That title... That title is the absolute coolest thing I've ever heard!",
  ui_story_5022_50220101_83_dialog_content = "Don't say that! You're embarrassing me...",
  ui_story_5022_50220101_84_dialog_content = "Ahem... I apologize for the unnecessary outburst just now.",
  ui_story_5022_50220101_85_dialog_content = "It seems I still have much training to do if I wish to become a warrior of Astra.",
  ui_story_5022_50220101_86_dialog_content = "Please, allow me to lead the way to the princess. May the winds guide us...",
  ui_story_5022_50220101_87_dialog_content = "... And that's where things lie at the moment. I'll send word through the Courier Union right away if anything changes.",
  ui_story_5022_50220101_88_dialog_content = "Sure, but... are you sure you don't need more people, Azure?",
  ui_story_5022_50220101_89_dialog_content = "Those fellows in Umbraton caused a real mess with those illicit drugs last time.",
  ui_story_5022_50220101_90_dialog_content = "Not this again... I told you before, I prefer to work alone. Anyone else would just get in my way.",
  ui_story_5022_50220101_91_dialog_content = "Quit treating me like a child.",
  ui_story_5022_50220101_92_dialog_content = "I know, I know! It's just...",
  ui_story_5022_50220101_93_dialog_content = "Help! I think something's wrong with my alarm bomb! It's not exploding like it used to...",
  ui_story_5022_50220101_94_dialog_content = "Let me take a look... Just pull out the fuse like this, and give it a pat or two, and... There, good as new.",
  ui_story_5022_50220101_95_dialog_content = "Have the snacks for Lepidoz arrived yet?",
  ui_story_5022_50220101_96_dialog_content = "Brock and Fleur were helping to deliver them. If they haven't made it yet... Chances are, Brock ate them while no one was looking.",
  ui_story_5022_50220101_97_dialog_content = "If that's the case, just feed Brock to Lepidoz. I'm sure it won't mind.",
  ui_story_5022_50220101_98_dialog_content = "We need to expand the warehouse here in Oasis! I hardly have any space to store my machine parts!",
  ui_story_5022_50220101_99_dialog_content = "Why not try hanging some of your parts from the ceiling? We just got some nice, sturdy rope, right over there.",
  ui_story_5022_50220101_100_dialog_content = "Or, you can use it to tie up Jomu for a few days, until he agrees to make some space for you.",
  ui_story_5022_50220101_101_dialog_content = "About that shipment from two days ago...",
  ui_story_5022_50220101_102_dialog_content = "Warehouse 6, in a crate covered by a tarp. Try to be careful, would you? Those little buggers bite, and their poison is no joke, either.",
  ui_story_5022_50220101_103_dialog_content = "As for today's supplies...",
  ui_story_5022_50220101_104_dialog_content = "The list is on the wall over there. I'll take a look later.",
  ui_story_5022_50220101_105_dialog_content = "Uh... Sorry Azure, I hardly get the chance to talk to you and here I am... What were we talking about just now?",
  ui_story_5022_50220101_106_dialog_content = "Princess! Your most esteemed warrior has returned!",
  ui_story_5022_50220101_107_dialog_content = "And now I'm a princess, huh... This day isn't getting any easier...",
  ui_story_5022_50220101_108_dialog_content = "Ahem... Praise the wind's guidance for leading you back to my side, noble warrior. What of the strife at our kingdom's borders?",
  ui_story_5022_50220101_109_dialog_content = "The demonic forces have been brazen in their attacks on the frontier villages, but worry not, Your Highness. My trusted companions and I made short work of the vile fiends!",
  ui_story_5022_50220101_110_dialog_content = "As a token of their gratitude, many of the village maidens offered us candy for protecting them from evil.",
  ui_story_5022_50220101_111_dialog_content = "I see... Then the Eclipsites have been routed for the time being.",
  ui_story_5022_50220101_112_dialog_content = "A number of villages have sprung up in the area since we agreed to help protect the local water source. Could the Eclipsite attacks have something to do with this...?",
  ui_story_5022_50220101_113_dialog_content = "You appear troubled, Your Highness. How may I be of assistance?",
  ui_story_5022_50220101_114_dialog_content = "It breaks my heart to see such a fair face tarnished by anguish...",
  ui_story_5022_50220101_115_dialog_content = "F-Fair...? Er... You have already done more than enough, my brave hero.",
  ui_story_5022_50220101_116_dialog_content = "The hand of fate recommends you wash off the weariness of your travels and enjoy some well-deserved rest. My aid is always available if you require someone to braid your hair.",
  ui_story_5022_50220101_117_dialog_content = "Well, look at you. You sure won Mommy's approval today, Zeta! Not bad, not bad!",
  ui_story_5022_50220101_X117_dialog_content = "Mom... You mean me?",
  ui_story_5022_50220101_118_dialog_content = "—Pffffft!",
  ui_story_5022_50220101_119_dialog_content = "Sigh... Every time you two run into each other...",
  ui_story_5022_50220101_120_dialog_content = "Alright, who else needs Mommy's help today? Hmm? Is that a new face I see?",
  ui_story_5022_50220101_121_dialog_content = "Yup! Allow me to introduce you to a young friend with mystical powers—PlayerName, the last of the Caelestites!",
  ui_story_5022_50220101_122_dialog_content = "I see... Nice to meet you. Name's Roy. Just a regular guy managing logistics and repairs for the Rediesel Wrench.",
  ui_story_5022_50220101_123_dialog_content = "Sinsa rarely brings friends over... The last of the Caelestites, huh?",
  ui_story_5022_50220101_124_dialog_content = "Well, any friend of the leader is a friend of ours, as well as an esteemed guest of the Rediesel Wrench. Welcome, PlayerName.",
  ui_story_5022_50220101_125_dialog_content = "If you're here at this time of year, it can only be for the Blazing Rally, right? Now that I think of it, it's time to settle on a venue.",
  ui_story_5022_50220101_126_dialog_content = "You mean you haven't even decided where to hold the race yet?!",
  ui_story_5022_50220101_127_dialog_content = "Yes, there are many tracks but we only choose which one to hold the race on one day in advance.",
  ui_story_5022_50220101_128_dialog_content = "Even so, Lumopolis forces have this tendency to show up looking for wanted criminals and lost vehicles.",
  ui_story_5022_50220101_129_dialog_content = "Of course, there's fun to be had in being surrounded as well.",
  ui_story_5022_50220101_130_dialog_content = "Th-That sounds exciting...",
  ui_story_5022_50220101_131_dialog_content = "(... I'm too familiar with everyone, so I sometimes forget that they're a group of wandering bandits...)",
  ui_story_5022_50220101_132_dialog_content = "Ahaha! But I shouldn't go on about that. We have guests. We should behave ourselves. Do you have any ideas, leader?",
  ui_story_5022_50220101_133_dialog_content = "Well, if we want our Caelestite friend to expand their horizons, there's always the <color=#FFB400>Blazing Tooth</color>.",
  ui_story_5022_50220101_134_dialog_content = "I bet those soft nobles, aging soldiers, and mercenaries don't have the grit to follow us all the way into the desert.",
  ui_story_5022_50220101_135_dialog_content = "No! That place is close to my patrol area. No one can beat me there, it'll be boring!",
  ui_story_5022_50220101_136_dialog_content = "The weather's great, so why don't we go to the Nightmare Ouroboro by the Gold River?",
  ui_story_5022_50220101_137_dialog_content = "Or we can go to the Green Hell next to the Whispering Corridor and rile up some Umbraton dolts!",
  ui_story_5022_50220101_138_dialog_content = "(So this kid can talk normally after all!)",
  ui_story_5022_50220101_139_dialog_content = "Hm... The Blazing Tooth is a classic route.",
  ui_story_5022_50220101_140_dialog_content = "But the track is very difficult, and the logistics team often complains about the aftermath. What's more, there are still Eclipsites appearing, even with regular sweeps.",
  ui_story_5022_50220101_141_dialog_content = "According to Zeta's report, the Eclipsites have been unusually active recently, which will require some looking into.",
  ui_story_5022_50220101_142_dialog_content = "I've got a feeling there could be a big one in the area, but I might just be overthinking it...",
  ui_story_5022_50220101_143_dialog_content = "...!",
  ui_story_5022_50220101_144_dialog_content = "A big one? Could it be the legendary <color=#FFB400>Wicked Dragon Hakudoma</color>?",
  ui_story_5022_50220101_145_dialog_content = "Um, is that what it was called?",
  ui_story_5022_50220101_146_dialog_content = "I made it up! It's cool, right? Right?",
  ui_story_5022_50220101_147_dialog_content = "I thought it was a good fit after hearing the story you told me about it.",
  ui_story_5022_50220101_148_dialog_content = "A story, huh... How carefree...",
  ui_story_5022_50220101_149_dialog_content = "Hey, Roy, I'll check out the area on my own tomorrow.",
  ui_story_5022_50220101_150_dialog_content = "You just relax and play racing games with the kids.",
  ui_story_5022_50220101_151_dialog_content = "You... You're saying that I'm a kid?",
  ui_story_5022_50220101_152_dialog_content = "And that the Blazing Rally is a game?!",
  ui_story_5022_50220101_153_dialog_content = "Not just that, you want to have all the fun challenging the wicked dragon on your own?!",
  ui_story_5022_50220101_154_dialog_content = "This will not stand. I challenge you to a racing duel!",
  ui_story_5022_50220101_155_dialog_content = "Tsk, troublesome brat...",
  ui_story_5022_50220101_156_dialog_content = "I'll beat you in the rally!",
  ui_story_5022_50220101_157_dialog_content = "And if the dragon appears, I'll charge ahead of you and destroy it, just like the heroes in the stories!",
  ui_story_5022_50220101_158_dialog_content = "...Probably.",
  ui_story_5022_50220101_159_dialog_content = "I don't have the time to play your little games.",
  ui_story_5022_50220101_160_dialog_content = "D-Don't go! Don't pretend you didn't hear me. I'll drag you to the registration booth if I have to!",
  ui_story_5022_50220101_161_dialog_content = "Hey! Don't think you can walk away just because you have long legs! Wait for me!",
  ui_story_5022_50220101_162_dialog_content = "Ooh. Now, this is interesting.",
  ui_story_5022_50220101_163_dialog_content = "A duel?",
  ui_story_5022_50220101_164_dialog_content = "In the Rediesel Wrench, duels are a serious matter. The challenged person must accept the challenge.",
  ui_story_5022_50220101_165_dialog_content = "To protect their honor? I actually had no idea the Rediesel Wrench could be so...",
  ui_story_5022_50220101_166_dialog_content = "No. It's so everyone else can gather round and watch the fun.",
  ui_story_5022_50220101_167_dialog_content = "I guess I should've seen that coming...",
  ui_story_5022_50220101_168_dialog_content = "Hey, hey, it's important to have a show to watch.",
  ui_story_5022_50220101_169_dialog_content = "The duel rules are super lax, anything goes. Brock once challenged me to a roasted lizard-eating competition, and I won.",
  ui_story_5022_50220101_170_dialog_content = "Although we were both scolded by Roy afterwards...",
  ui_story_5022_50220101_171_dialog_content = "How many times have I told you guys not to eat snacks before bedtime? After that little stunt, our food reserves—",
  ui_story_5022_50220101_172_dialog_content = "Ahem! So, looks like the track is decided and it's the Blazing Tooth. No objections? Good. Roy, I still gotta show our guest around!",
  ui_story_5022_50220101_173_dialog_content = "Well, if the leader says so...",
  ui_story_5022_50220101_174_dialog_content = "I should go prepare for the race too.",
  ui_story_5022_50220101_175_dialog_content = "PlayerName, you should look forward to it!",
  ui_story_5022_50220201_1_dialog_content = "(How did I end up here... And this is just the beginning...)",
  ui_story_5022_50220201_2_dialog_content = "<size=45>—Take this! Lightning Shot!</size>",
  ui_story_5022_50220201_3_dialog_content = "It's not a proper Blazing Rally without it! Hey, losers up front! Are ya burning yet?!",
  ui_story_5022_50220201_4_dialog_content = "You idiot! I'll show you what a classic rally weapon looks like! Eat caltrops, you parasite!",
  ui_story_5022_50220201_5_dialog_content = "Uaaargh! We're gonna run right over them!",
  ui_story_5022_50220201_6_dialog_content = "Cute. Their tricks are so old, I'm getting all nostalgic over here!",
  ui_story_5022_50220201_7_dialog_content = "(We somehow came out unscathed...)",
  ui_story_5022_50220201_8_dialog_content = "Ah, that's better. Quieter.",
  ui_story_5022_50220201_9_dialog_content = "So, time for explanations.",
  ui_story_5022_50220201_S9_dialog_content = "Why are you in my passenger seat, Caelestite?",
  ui_story_5022_50220201_10_dialog_content = "C-Can you not get so close? Azure! Eyes on the road! The road!",
  ui_story_5022_50220201_11_dialog_content = "Sinsa told me to sit here and wait for him, but then the starting gun went off and he still hadn't appeared.",
  ui_story_5022_50220201_12_dialog_content = "Instead, what appeared was...",
  ui_story_5022_50220201_13_dialog_content = "Forget it. I don't mind spending some alone time with such a cute kid, as long as you don't give me trouble.",
  ui_story_5022_50220201_14_dialog_content = "T-To be honest, I wasn't expecting there to be a chain of crashes right at the start... all the competitors are so brutal...",
  ui_story_5022_50220201_15_dialog_content = "What kind of rally is this?!",
  ui_story_5022_50220201_16_dialog_content = "You've got guts to be getting into my car without even knowing a thing about this event.",
  ui_story_5022_50220201_17_dialog_content = "Sinsa was too busy dragging me to eat scorpion pie to explain anything...",
  ui_story_5022_50220201_18_dialog_content = "Your driving's pretty impressive for getting us out of that chaos.",
  ui_story_5022_50220201_19_dialog_content = "Hm, you're a bit ditzy, but quite the flatterer, aren't you?",
  ui_story_5022_50220201_20_dialog_content = "Anyway, it's nothing. This is just a game, and being serious about it is what I should be doing.",
  ui_story_5022_50220201_21_dialog_content = "What about the duel?",
  ui_story_5022_50220201_22_dialog_content = "What a silly question. Yes, I accepted the challenge, but so what if that little idiot wins?",
  ui_story_5022_50220201_23_dialog_content = "What's more important is tracking the movements of the Eclipsites.",
  ui_story_5022_50220201_24_dialog_content = "So we can prevent a repeat of those events...",
  ui_story_5022_50220201_25_dialog_content = "Speaking of which, the legendary wicked dragon—",
  ui_story_5022_50220201_26_dialog_content = "Woah!",
  ui_story_5022_50220201_27_dialog_content = "What was that just now?",
  ui_story_5022_50220201_28_dialog_content = "Do you always ask so many questions? I'm starting to regret letting you stay in the car.",
  ui_story_5022_50220201_29_dialog_content = "I just ran over an Eclipsite, that's all. It wasn't fatal from the feel of it, and it'll probably catch up later.",
  ui_story_5022_50220201_30_dialog_content = "... Catch up?",
  ui_story_5022_50220201_31_dialog_content = "Uh-huh, there should be more Eclipsites up ahead too.",
  ui_story_5022_50220201_32_dialog_content = "More...?",
  ui_story_5022_50220201_33_dialog_content = "Who knows, maybe I'll even find that one Eclipsite I've been looking for.",
  ui_story_5022_50220201_34_dialog_content = "It's not too late for you to run for your life if you're afraid.",
  ui_story_5022_50220201_35_dialog_content = "Even someone like you should be able to run across this patch of desert and get back to the starting point.",
  ui_story_5022_50220201_36_dialog_content = "Erm...",
  ui_story_5022_50220201_37_dialog_content = "Heh... Kidding! Your flustered expression is more amusing than I'd thought.",
  ui_story_5022_50220201_38_dialog_content = "What a pity, looks like our sweet alone time is about to get interrupted.",
  ui_story_5022_50220201_39_dialog_content = "W-What...?",
  ui_story_5022_50220201_40_dialog_content = "—Yoohoo! PlayerName!",
  ui_story_5022_50220201_41_dialog_content = "Yawn... Look like we overslept and missed the start of the competition.",
  ui_story_5022_50220201_42_dialog_content = "That was you! I didn't miss anything!",
  ui_story_5022_50220201_43_dialog_content = "Landing on one tire, zipping between crevices past the guys blocking the road, that's the way Miss Azure does it!",
  ui_story_5022_50220201_44_dialog_content = "Wait, the car's been moving this whole time. How did you guys even get in here?",
  ui_story_5022_50220201_45_dialog_content = "From the roof!",
  ui_story_5022_50220201_46_dialog_content = "Nice. And here I thought you two would've gotten shaken off at the impact earlier and faceplanted into the sand.",
  ui_story_5022_50220201_47_dialog_content = "You were sleeping so soundly in my car without permission, I felt you deserved a special kind of wakeup call.",
  ui_story_5022_50220201_48_dialog_content = "Don't be so cold! I had to get front row seats for the return of the former rally champion.",
  ui_story_5022_50220201_49_dialog_content = "PlayerName, I got you a good seat, didn't I? You can thank me later.",
  ui_story_5022_50220201_50_dialog_content = "Azure is my senior, she joined the Rediesel Wrench before I did.",
  ui_story_5022_50220201_51_dialog_content = "More importantly, she's a legendary racer!",
  ui_story_5022_50220201_52_dialog_content = "Legendary, huh? That's in the past.",
  ui_story_5022_50220201_53_dialog_content = "The only reason I can think of for your presence is... Hmph. Meddlers.",
  ui_story_5022_50220201_54_dialog_content = "Young Sinsa here isn't an adorable junior at all, but he's still the leader.",
  ui_story_5022_50220201_55_dialog_content = "He's said the word, so I'll let you guys stay.",
  ui_story_5022_50220201_56_dialog_content = "But let me make this clear: I'm travelling to the Blazing Tooth area to investigate the Eclipsites. My route just so happens to overlap with the racetrack.",
  ui_story_5022_50220201_57_dialog_content = "Looks like we've got more hitchhikers coming up behind us...",
  ui_story_5022_50220201_58_dialog_content = "How should naughty children be punished?",
  ui_story_5022_50220202_1_dialog_content = "Did Azure's racecar just fire a cannon at the Eclipsites chasing behind us...?",
  ui_story_5022_50220202_2_dialog_content = "You know what, at this point, nothing really fazes me anymore.",
  ui_story_5022_50220202_3_dialog_content = "<size=45>Hello, everyone—!</size>This is your host, Jomu! Miss me?",
  ui_story_5022_50220202_4_dialog_content = "Whoa! What's that?",
  ui_story_5022_50220202_5_dialog_content = "The Blazing Rally lives up to its name by starting with a bang...",
  ui_story_5022_50220202_6_dialog_content = "That's right, half our contestants have already gotten eliminated at their starting points!",
  ui_story_5022_50220202_7_dialog_content = "Unfortunately, some of them were collateral damage in others' crashes. But luck is also part of the game here!",
  ui_story_5022_50220202_8_dialog_content = "Rest assured to all the defeated lying amongst wreckage!",
  ui_story_5022_50220202_9_dialog_content = "Rabbie and Chainsaw Rick from Logistics Team 6 will be right over to extract you all from your vehicles in due course!",
  ui_story_5022_50220202_10_dialog_content = "Those still in the race are currently shooting towards the first stage, the <color=#FFB400>Hot Air Desert</color>, at full speed!",
  ui_story_5022_50220202_11_dialog_content = "Let's sit tight and see what exciting spectacles lie ahead!",
  ui_story_5022_50220202_12_dialog_content = "Is this... a live broadcast?",
  ui_story_5022_50220202_13_dialog_content = "As always, the Blazing Rally is sponsored exclusively by none other than Rediesel Wrench.",
  ui_story_5022_50220202_14_dialog_content = "Rediesel Wrench, your best buddy in the desert.",
  ui_story_5022_50220202_15_dialog_content = "We offer village security, machine repairs, recycling, fighting, and other services for your convenience!",
  ui_story_5022_50220202_16_dialog_content = "The rates... well, they're cheaper than Illumina anyhow, and we guarantee transparency!",
  ui_story_5022_50220202_17_dialog_content = "Place an order now and get a handmade mini figurine of Rediesel Wrench's famous Lepidoz!",
  ui_story_5022_50220202_X17_dialog_content = "Stock is limited, so it's first come, first serve! Don't miss out!",
  ui_story_5022_50220202_18_dialog_content = "Up next, let's announce the results of the last race's audience survey...",
  ui_story_5022_50220202_19_dialog_content = "The feedback with the most votes: Can we get rid of the loud announcer?",
  ui_story_5022_50220202_20_dialog_content = "Thank you! Your satisfaction is our motivation to improve!",
  ui_story_5022_50220202_21_dialog_content = "Unfortunately, everyone else is either too shy or finds this task too much trouble, so I am still the host of this year's race!",
  ui_story_5022_50220202_22_dialog_content = "As compensation, however, I've invited guest commentators for you!",
  ui_story_5022_50220202_23_dialog_content = "We will be broadcasting from the official radio station on Lepidoz, sharing news about the race and a whole host of other messages!",
  ui_story_5022_50220202_24_dialog_content = "... What? You want me to sit here? I have other important things to⁠—",
  ui_story_5022_50220202_25_dialog_content = "You really want an oldie like me doing this? I can't come up with anything amusing to say...",
  ui_story_5022_50220202_26_dialog_content = "(He clearly just got randomly roped into doing this!)",
  ui_story_5022_50220202_27_dialog_content = "And now, let's have...",
  ui_story_5022_50220202_28_dialog_content = "Oh, I mean, let's have our guest commentator Roy introduce the rules of the competition to our friends who are new to this!",
  ui_story_5022_50220202_29_dialog_content = "Uh... Rules? We don't do any of that boring stuff.",
  ui_story_5022_50220202_30_dialog_content = "Anyone who signs up can use any vehicle to complete the designated course. All you've gotta do is stay on the vehicle for as long as possible, and complete the course as fast as you can.",
  ui_story_5022_50220202_31_dialog_content = "Precisely! Conquer nature with bravado, push yourself beyond limitations!",
  ui_story_5022_50220202_32_dialog_content = "Let the fire in your engines and your heart propel you in battle!",
  ui_story_5022_50220202_33_dialog_content = "Is there anything else our guest commentator would like to add?",
  ui_story_5022_50220202_34_dialog_content = "Is there anything else to add? I guess... Have fun, and try to come back alive.",
  ui_story_5022_50220202_35_dialog_content = "Feel free to go wild. As long as there's still life left in you, there's nothing the logistics team can't do.",
  ui_story_5022_50220202_36_dialog_content = "Excellent! As expected from Roy, unleashing such an extreme statement so casually!",
  ui_story_5022_50220202_37_dialog_content = "And this isn't the only surprise we prepared this year.",
  ui_story_5022_50220202_38_dialog_content = "The legendary undefeated driver, known as the Rediesel Race's Sexy Wildcat, is back on the tracks for the first time in a decade!",
  ui_story_5022_50220202_39_dialog_content = "Jomu...!",
  ui_story_5022_50220202_40_dialog_content = "(There's an intensely dangerous aura emanating from Azure...)",
  ui_story_5022_50220202_41_dialog_content = "I've never heard that nickname in my life... She's gonna put a target on you soon, it's not too late for damage control.",
  ui_story_5022_50220202_42_dialog_content = "It's a small sacrifice to make for the sake of the show.",
  ui_story_5022_50220202_43_dialog_content = "And speaking of!",
  ui_story_5022_50220202_44_dialog_content = "Word is that the powerful Eclipsite that appeared in Blazing Tooth over ten years ago—",
  ui_story_5022_50220202_45_dialog_content = "—The Wicked Dragon Hakudoma, might show up again!",
  ui_story_5022_50220202_46_dialog_content = "When did that name become official... Well, Zeta's gonna love it.",
  ui_story_5022_50220202_47_dialog_content = "Anyways, I came because I wanted to discuss the prizes with you.",
  ui_story_5022_50220202_48_dialog_content = "Almost forgot! The prizes for this year are the most luxurious yet!",
  ui_story_5022_50220202_49_dialog_content = "As always, it's first come first serve, and they include a Lepidoz one-day interactive ticket, Barbara and Regina's...",
  ui_story_5022_50220202_50_dialog_content = "The prizes are gone.",
  ui_story_5022_50220202_51_dialog_content = "Huh? What do you mean by that?",
  ui_story_5022_50220202_52_dialog_content = "Lepidoz ate the one-day interactive ticket.",
  ui_story_5022_50220202_53_dialog_content = "Barbara and Regina didn't want to put their respective albums up together, and the explosive hobbyists had an annual six-in-one member selection...",
  ui_story_5022_50220202_54_dialog_content = "Joanie Boom won, but she couldn't resist temptation and set off her bomb before the race even began.",
  ui_story_5022_50220202_55_dialog_content = "She said something about not having tested it after making it, then sent a sharp sandstone blasting into the sky.",
  ui_story_5022_50220202_56_dialog_content = "I thought it was pretty decent, but she kept insisting that the flame's color could do with more aesthetic improvements.",
  ui_story_5022_50220202_57_dialog_content = "Okay, let me correct myself—",
  ui_story_5022_50220202_58_dialog_content = "It appears that the prizes for this year's race will be the same as in previous years: my own top secret protein powder mix...",
  ui_story_5022_50220202_59_dialog_content = "And a handmade animal doll from an anonymous donor!",
  ui_story_5022_50220202_60_dialog_content = "In addition, every racer gets a participation prize!",
  ui_story_5022_50220202_61_dialog_content = "Which would be—",
  ui_story_5022_50220202_62_dialog_content = "The experience of being alive, of hot passion bubbling through your veins, and the joy of laughing with everyone amidst the wind, beneath the torrid sunshine!",
  ui_story_5022_50220202_63_dialog_content = "(Can this radio station be turned off...?)",
  ui_story_5022_50220202_64_dialog_content = "Hold on! For those of you about to turn off the radio, we have one more mystery prize to be revealed later!",
  ui_story_5022_50220202_65_dialog_content = "The exciting stuff starts here. But first, an important message—",
  ui_story_5022_50220202_66_dialog_content = "Octobro Shaved Ice, the shaved iced stall in front of the Tir' Hotel, recently launched a new product!",
  ui_story_5022_50220202_67_dialog_content = "It's called Lies Taste Like Sweet Honey. Just piques one's interest, doesn't it? Everyone who participated in the taste test, be it Aurorian or Wolf, said...",
  ui_story_5022_50220202_68_dialog_content = "Phew, that's finally over. Are people even into prizes like that...",
  ui_story_5022_50220202_69_dialog_content = "Ha, you never know.",
  ui_story_5022_50220202_70_dialog_content = "Rediesel Wrench members have always been in charge of gathering the prizes. We've had even worse in previous years.",
  ui_story_5022_50220202_71_dialog_content = "The thing is, even if there were no prizes involved, people would still come just to have fun.",
  ui_story_5022_50220202_72_dialog_content = "(Is Miss Azure... smiling?)",
  ui_story_5022_50220202_73_dialog_content = "...Azure, could it be that you actually really like the Blazing Rally...?",
  ui_story_5022_50220202_74_dialog_content = "We've only just met and you're already trying to get inside my head. Not a smart way of hitting on someone, Caelestite.",
  ui_story_5022_50220202_75_dialog_content = "H-How should I put it... This event is crazy. Is this how the Rediesel Wrench does things...?",
  ui_story_5022_50220202_76_dialog_content = "What are you muttering about?",
  ui_story_5022_50220202_77_dialog_content = "Zeta?",
  ui_story_5022_50220202_78_dialog_content = "Oh? I can't believe you recognized my voice so quickly.",
  ui_story_5022_50220202_79_dialog_content = "You're really not a casual purveyor... Master of the Colossus, guide of light, last of the Caelestites.",
  ui_story_5022_50220202_80_option_content = "Just call me PlayerName.",
  ui_story_5022_50220202_81_dialog_content = "Dummy! It's a great title! It's such a waste to not use it more!",
  ui_story_5022_50220202_82_dialog_content = "Let's see... Right, so why are we being graced with the presence of Miss Sweet Devil on the communication channel?",
  ui_story_5022_50220202_83_dialog_content = "You... You're taking me for a fool, aren't you?!",
  ui_story_5022_50220202_84_dialog_content = "Isn't that the team name you came up with? Miss—Sweet—Devil.",
  ui_story_5022_50220202_85_dialog_content = "Don't laugh when you say it!",
  ui_story_5022_50220202_86_option_content = "Heheh, you flatter me.",
  ui_story_5022_50220202_87_dialog_content = "Oh? I didn't expect you to be so into roleplay. How cute.",
  ui_story_5022_50220202_88_dialog_content = "Well then... Miss Sweet Devil, what do you want from my Caelestite?",
  ui_story_5022_50220202_89_dialog_content = "\"My\"...?",
  ui_story_5022_50220202_90_dialog_content = "Don't... Don't laugh whenever you bring up the name I put so much effort into creating!",
  ui_story_5022_50220202_91_dialog_content = "I'm just here to see why you cannon fodder are so slow!",
  ui_story_5022_50220202_92_dialog_content = "Isn't your team name Sweet Devil? It evokes a confusing image...",
  ui_story_5022_50220202_93_dialog_content = "Last year it was Child of the Wilderness or something...",
  ui_story_5022_50220202_94_dialog_content = "Berserker Sinsa! Why are you in that woman's car...? Have you betrayed your mission?!",
  ui_story_5022_50220202_95_dialog_content = "Uh, that's... It's...",
  ui_story_5022_50220202_96_dialog_content = "Hehehe. I know, you're just pretending to be taken in by her, but you're actually waiting for an opportunity to help me stall her progress...",
  ui_story_5022_50220202_97_dialog_content = "I appreciate your efforts, but I intend to fight her fair and square!",
  ui_story_5022_50220202_98_dialog_content = "Looks like the starting line chaos wasn't enough to finish you off.",
  ui_story_5022_50220202_99_dialog_content = "Although it's surprising that just a few little bombs caused such a ruckus...",
  ui_story_5022_50220202_100_dialog_content = "No, the tailgating happened mostly because a certain baldie pulled out a missile launcher!",
  ui_story_5022_50220202_101_dialog_content = "Ohohoho! Tremble, Caelestite!",
  ui_story_5022_50220202_102_dialog_content = "She's not listening at all.",
  ui_story_5022_50220202_103_dialog_content = "I host the power of a demon god within me... I am the devil! I am the menace! Misunderstood by all in the world...",
  ui_story_5022_50220202_104_dialog_content = "...Yet there is the spirit of a kind warrior within me!",
  ui_story_5022_50220202_105_dialog_content = "She's acting like she's not listening, yet she clearly just patched up the plot hole in her story...",
  ui_story_5022_50220202_106_dialog_content = "Thus... I will make you see defeat, Azure.",
  ui_story_5022_50220202_107_dialog_content = "Otherwise known as Absolute Zero Witch, lackey of one of the four Heavenly Kings, the Demon King!",
  ui_story_5022_50220202_108_dialog_content = "Who in the world are the Demon King and the other three... You know what, I don't wanna know.",
  ui_story_5022_50220202_109_dialog_content = "I have to admit, I prefer Absolute Zero Witch to Sexy Wildcat.",
  ui_story_5022_50220202_110_dialog_content = "Ever since the first year I won the Blazing Rally...",
  ui_story_5022_50220202_111_dialog_content = "Fools have been comparing my record to yours, saying that if you hadn't left the tracks, perhaps I would never have a shot at winning.",
  ui_story_5022_50220202_112_dialog_content = "And you're always going on dangerous quests saying you want to train up your strength, making Roy worry about you!",
  ui_story_5022_50220202_113_dialog_content = "No more words need be spoken. Our lives have already been woven together by the Hand of Fate.",
  ui_story_5022_50220202_114_dialog_content = "Racer of the legends, you'd better not disappoint me.",
  ui_story_5022_50220202_115_dialog_content = "She even added some extra flourish at the end...",
  ui_story_5022_50220202_116_dialog_content = "It's amusing to watch someone try so hard, isn't it? Despite that, she doesn't have what it takes to be naughty.",
  ui_story_5022_50220202_117_dialog_content = "But as a racer, she's an opponent who shouldn't be underestimated.",
  ui_story_5022_50220202_118_dialog_content = "Did you hear the wind in the background of her transmission? There were interferences but I'm sure of it.",
  ui_story_5022_50220202_119_dialog_content = "Zeta got ahead of everyone else and is already in the Hot Air Desert.",
  ui_story_5022_50220202_120_dialog_content = "As the designated antagonist to her protagonist, I'm gonna have to up my game.",
  ui_story_5022_50220301_1_dialog_content = "*Yawn* Where are we?",
  ui_story_5022_50220301_2_dialog_content = "Ooh! Aren't we already in the Hot Air Desert?",
  ui_story_5022_50220301_3_dialog_content = "I have some sandworm jerky here. Want some? I'll eat them if you don't want them.",
  ui_story_5022_50220301_4_dialog_content = "You guys know this isn't a picnic, right?",
  ui_story_5022_50220301_5_dialog_content = "Heheh, I was looking forward to today so much that I didn't sleep at all last night!",
  ui_story_5022_50220301_6_dialog_content = "Between Azure's fast, steady driving and Jomu's droning, I got so sleepy...",
  ui_story_5022_50220301_7_dialog_content = "Speaking of which, Jomu's supposed to be the announcer, but it's just one ad after another and nothing about the actual race!",
  ui_story_5022_50220301_8_dialog_content = "The starting points are different, but all contestants pass through the checkpoint in the Hot Air Desert on their way to the service station at Dragon Breath Volcano.",
  ui_story_5022_50220301_9_dialog_content = "Then they go through Blazing Tooth Canyon, to finally reach the far edge of Eternal Night.",
  ui_story_5022_50220301_10_dialog_content = "As the name indicates, it's a track to the end of the world.",
  ui_story_5022_50220301_11_dialog_content = "The end of the world...",
  ui_story_5022_50220301_12_dialog_content = "The weather seems nice today, so we shouldn't encounter sandstorms. The last time we raced, sand was hitting us in the face...",
  ui_story_5022_50220301_13_dialog_content = "There are sandstorms? That sounds really risky...",
  ui_story_5022_50220301_14_dialog_content = "Don't worry, even if you get swept up into the sky, there's always a way out!",
  ui_story_5022_50220301_15_dialog_content = "Hmm. We should be running into other competitors soon.",
  ui_story_5022_50220301_16_dialog_content = "Ooh! Look, PlayerName, look!",
  ui_story_5022_50220301_17_dialog_content = "That's...",
  ui_story_5022_50220301_18_dialog_content = "Watch out!",
  ui_story_5022_50220301_19_dialog_content = "Tsk, tsk. Good thing Honcho Sinsa was quick and pulled you back.",
  ui_story_5022_50220301_20_dialog_content = "You know this isn't a picnic, right, PlayerName?",
  ui_story_5022_50220301_21_dialog_content = "Was that Clover's Shadow Windmill that just nearly sliced off a chunk of my hair?",
  ui_story_5022_50220301_22_dialog_content = "Hey, that's dangerous! You have to pay if you make me lose any of my feathers!",
  ui_story_5022_50220301_23_dialog_content = "U-Um, g-guys... Don't fight... Moving about is dangerous...",
  ui_story_5022_50220301_24_dialog_content = "Waaaah! I'm way better with a motorcycle compared to this...",
  ui_story_5022_50220301_25_dialog_content = "That bear started it.",
  ui_story_5022_50220301_26_dialog_content = "Don't use me as a scapegoat!",
  ui_story_5022_50220301_27_dialog_content = "<size=45>Of course I didn't receive a commission to come to this hot-as-hell place to participate in this race and tell Kuma to ambush you to increase my chances of winning!</size>",
  ui_story_5022_50220301_28_dialog_content = "Pengy, not used, to lying.",
  ui_story_5022_50220301_29_dialog_content = "Work with me, partner! Do you know what I have to go through just to make us a living?",
  ui_story_5022_50220301_30_dialog_content = "Sounds like Mr. Pengy has his work cut out for him...",
  ui_story_5022_50220301_31_dialog_content = "Maggie, eyes on the road. Be wary of sand slopes.",
  ui_story_5022_50220301_32_dialog_content = "Aha! An opening!",
  ui_story_5022_50220301_33_dialog_content = "... Well, I wish, but I can't get through... this girl is so eerily calm.",
  ui_story_5022_50220301_34_dialog_content = "Shut up!!! Stop disturbing my sleep! Wanna eat bullets?!",
  ui_story_5022_50220301_35_dialog_content = "A-An ambush?! Taste the power of these shells! Arctic—",
  ui_story_5022_50220301_36_dialog_content = "Diverting attention, fake shells, and all blasted away. So quick.",
  ui_story_5022_50220301_37_dialog_content = "B-Before I could even use Luminatics, you...",
  ui_story_5022_50220301_38_dialog_content = "Huh? Isn't this Miss Kafka?!",
  ui_story_5022_50220301_39_dialog_content = "What the, it's you two.... So you finally decided to join Rediesel Wrench?",
  ui_story_5022_50220301_40_dialog_content = "Woof?",
  ui_story_5022_50220301_41_dialog_content = "Don't think so little of us. Unlike this crocodile here, we wouldn't join you people just for some lousy pool and three meals a day.",
  ui_story_5022_50220301_42_dialog_content = "Oi, don't think I can't kick you out of the car just because I'm driving. Or do you want to be turned into a downy pillow?",
  ui_story_5022_50220301_43_dialog_content = "Yeah! You guys really like that pool, right?",
  ui_story_5022_50220301_44_dialog_content = "We do indeed spend a lot of time cooling off by the pool at the Oasis, catching up on gossip and news via Rediesel Wrench.",
  ui_story_5022_50220301_45_dialog_content = "Miss Kafka also feeds us snacks once in a while, but...",
  ui_story_5022_50220301_46_dialog_content = "My wings of freedom will never be bought by these small niceties!",
  ui_story_5022_50220301_47_dialog_content = "I still have a headache from staying up late for work. I don't have time for your nonsense. Look here.",
  ui_story_5022_50220301_48_dialog_content = "Your shells were just a diversionary tactic. These cans of herring, however, are the real thing.",
  ui_story_5022_50220301_49_dialog_content = "!!!",
  ui_story_5022_50220301_50_dialog_content = "I'm going to toss them over.",
  ui_story_5022_50220301_51_dialog_content = "W-We've got this—",
  ui_story_5022_50220301_X51_dialog_content = "Me too—",
  ui_story_5022_50220301_X52_dialog_content = "Aaaahhhh!!",
  ui_story_5022_50220301_X53_dialog_content = "Pengy! Hang onto me!",
  ui_story_5022_50220301_52_dialog_content = "That stupid penguin didn't have to jump out of a speeding car just for a few cans...",
  ui_story_5022_50220301_53_dialog_content = "Kuma was trying to save him and fell too... They rolled so far away that I can't see them anymore.",
  ui_story_5022_50220301_54_dialog_content = "Must be the wings of freedom they were talking about... Really, no one beats them at clowning around.",
  ui_story_5022_50220301_55_dialog_content = "Alright, your two teammates are tumbling in the sand, Sork. They've pretty much given up.",
  ui_story_5022_50220301_56_dialog_content = "Those fish cans didn't go to waste. I know we're aiming for the same thing.",
  ui_story_5022_50220301_57_dialog_content = "Confrontation is inevitable.",
  ui_story_5022_50220301_58_dialog_content = "Awooooo!",
  ui_story_5022_50220301_59_dialog_content = "I don't understand... I really don't understand.",
  ui_story_5022_50220301_60_dialog_content = "Why... Why are the plushies that Roy makes just for fun so popular?",
  ui_story_5022_50220301_61_dialog_content = "Some collectors even hire Bounty Hunters at ludicrous prices just to get their hands on one.",
  ui_story_5022_50220301_62_dialog_content = "Because there might be a rabbit this time. You can't miss out on the rabbits.",
  ui_story_5022_50220301_63_dialog_content = "Bunnybear Plushes are no match for their fluffy texture. You're guaranteed a good night's sleep hugging one.",
  ui_story_5022_50220301_64_dialog_content = "Woof, woof!",
  ui_story_5022_50220301_65_dialog_content = "No matter what they look like... or what materials they're made of... It always feels like a gentle caress...",
  ui_story_5022_50220301_66_dialog_content = "Simple materials but delicately and exquisitely made. Makes for a perfect lounge chair in the nest.",
  ui_story_5022_50220301_67_dialog_content = "Bekk... Even you're a fan!?",
  ui_story_5022_50220301_68_dialog_content = "Kafka's right, chirp! This battle is inevitable.",
  ui_story_5022_50220301_69_dialog_content = "It's a rare opportunity. While we're at it, why not find out who's the better sniper than Rediesel Wrench?",
  ui_story_5022_50220301_70_dialog_content = "There's nowhere to hide! Franz, go!",
  ui_story_5022_50220301_71_dialog_content = "Chirp! Raging Bekk!",
  ui_story_5022_50220301_72_dialog_content = "My turn! M23 High Explosive!",
  ui_story_5022_50220301_73_dialog_content = "It seems rather lively over there... Shouldn't we do something about it?",
  ui_story_5022_50220301_74_dialog_content = "It's fine. Beating each other up is also part of the race.",
  ui_story_5022_50220301_75_dialog_content = "Getting familiar with each other's abilities will allow them to work better together in battle.",
  ui_story_5022_50220301_76_dialog_content = "I didn't realize it was that deep...",
  ui_story_5022_50220301_77_dialog_content = "Oh, I just randomly came up with that explanation. I impress even myself!",
  ui_story_5022_50220301_78_dialog_content = "Can't we distance ourselves from them and circle around?",
  ui_story_5022_50220301_79_dialog_content = "It's not that we can't, but this area is crawling with giant sandworms.",
  ui_story_5022_50220301_80_dialog_content = "If we stray from the path, we'd likely end up as sandworm snacks, car and all. Or worse, the quicksand would swallow us.",
  ui_story_5022_50220301_81_dialog_content = "But even the designated route takes us through their hunting grounds...",
  ui_story_5022_50220301_82_dialog_content = "By the way, I heard there were contestants who brought their own tamed giant sandworms in previous years.",
  ui_story_5022_50220301_83_dialog_content = "That's right. They did well, to my surprise, but I still won in the end.",
  ui_story_5022_50220301_84_dialog_content = "Whoa! There's a giant warhead coming this way! I wonder what color its explosion will be...",
  ui_story_5022_50220301_85_dialog_content = "Tsk... What a bunch of kids, scattering their toys all over like this.",
  ui_story_5022_50220301_86_dialog_content = "Are you seriously calling explosives \"toys\"?!",
  ui_story_5022_50220301_87_dialog_content = "Toys that hurt when stepped on. The two snipers look more professional, but the way they hold their guns could be more—",
  ui_story_5022_50220301_88_dialog_content = "Azure! Turn! Turn now!",
  ui_story_5022_50220301_89_dialog_content = "<color=#e8d9bb>BOOM!</color>",
  ui_story_5022_50220301_90_dialog_content = "Oh, just a regular yellow. Bo--ring.",
  ui_story_5022_50220301_91_dialog_content = "Whew, that was close... What a shockwave...",
  ui_story_5022_50220301_92_dialog_content = "You had enough fun? If we're gonna get moving, I've found a good route.",
  ui_story_5022_50220301_93_dialog_content = "Having Miss Azure here makes me feel safe. And that beautiful turn just now, I didn't even need to warn her...",
  ui_story_5022_50220301_94_dialog_content = "Nononono! What she calls a good route—",
  ui_story_5022_50220301_95_dialog_content = "Caelestite, do you like it rough?",
  ui_story_5022_50220301_96_dialog_content = "What?",
  ui_story_5022_50220301_97_dialog_content = "PlayerName, hurry! Hold onto something!",
  ui_story_5022_50220501_1_dialog_content = "(Was I dreaming?)",
  ui_story_5022_50220501_2_dialog_content = "(I dreamt of us charging towards a huge sand slope. The car blasted into the air, and time seemed to stand still.)",
  ui_story_5022_50220501_3_dialog_content = "(All around us were Eclipsites lurking in the shadows of the boulders. They all looked up, and I was met with the gaze of hundreds of pairs of eyes.)",
  ui_story_5022_50220501_4_dialog_content = "(The Eclipsites were quickly defeated, but then the sandy dunes began to sift apart...)",
  ui_story_5022_50220501_5_dialog_content = "(And something appeared from the ground... a mouth filled with teeth?)",
  ui_story_5022_50220501_6_dialog_content = "Was that... a dream?",
  ui_story_5022_50220501_7_dialog_content = "It was real.",
  ui_story_5022_50220501_8_dialog_content = "We're going pretty fast, so that hungry sandworm is Kafka's team's problem.",
  ui_story_5022_50220501_9_dialog_content = "Will they be alright?",
  ui_story_5022_50220501_10_dialog_content = "By the way, is this what you call \"liking it rougher\"?!",
  ui_story_5022_50220501_11_dialog_content = "Heyo! Are you all still alive, my listeners and contestants?",
  ui_story_5022_50220501_12_dialog_content = "I'm Jomu, your host. The Blazing Rally is really heating up now! Kill or be killed, people!",
  ui_story_5022_50220501_13_dialog_content = "Giant sandworms are occasional guests that like appearing abruptly, and they'll be found in the Hot Air Desert as well!",
  ui_story_5022_50220501_14_dialog_content = "Who knows if we'll get any more surprise visitors later in the race?",
  ui_story_5022_50220501_15_dialog_content = "For example, the legendary nine-headed, six-clawed, three-winged wicked dragon!",
  ui_story_5022_50220501_16_dialog_content = "You really will say anything to rile up the crowd. Have you even announced anything important yet?",
  ui_story_5022_50220501_17_dialog_content = "Odi from the communication division is collecting the signals of contestants giving up due to the sandworms' attacks. But before that...",
  ui_story_5022_50220501_18_dialog_content = "Everyone! The Eclipsite known as the Wicked Dragon is the same one that was driven away by our guest commentator years ago!",
  ui_story_5022_50220501_19_dialog_content = "What does Roy have to say about this old friend?",
  ui_story_5022_50220501_20_dialog_content = "Why all of a sudden... Well, yes. It was a pity that we weren't able to kill the Eclipsite back then.",
  ui_story_5022_50220501_21_dialog_content = "The stronghold had suffered an ambush by the Eclipsites. We were out of ammo, and its claws had pierced through me...",
  ui_story_5022_50220501_22_dialog_content = "But I still wish I'd tried harder back then.",
  ui_story_5022_50220501_23_dialog_content = "Pierced through you?!",
  ui_story_5022_50220501_24_dialog_content = "Oh, it was nothing. Anyway, I leave the fighting to the youngsters these days.",
  ui_story_5022_50220501_25_dialog_content = "That said, certain people should take it a little easier. Even if they have what it takes, they shouldn't always try to do things on their own...",
  ui_story_5022_50220501_26_dialog_content = "Since we're here, why not just relax a bit and enjoy the race?",
  ui_story_5022_50220501_27_dialog_content = "... So that creature really exists? I thought it was just something from Zeta's stories, like the evil god...",
  ui_story_5022_50220501_28_dialog_content = "You scared? Want a hug?",
  ui_story_5022_50220501_29_option_content = "I'm not!",
  ui_story_5022_50220501_30_dialog_content = "Is that so? Your false bravado is cute too.",
  ui_story_5022_50220501_31_option_content = "Yes, please!",
  ui_story_5022_50220501_32_dialog_content = "Oh? I love an honest kid. Sadly, I'm occupied right now.",
  ui_story_5022_50220501_33_dialog_content = "It's been gone for how many years now? No wonder the story has gotten so far-fetched.",
  ui_story_5022_50220501_34_dialog_content = "And now it shows up the very year I return... It's too much of a coincidence, no?",
  ui_story_5022_50220501_35_dialog_content = "But it did exist and still exists...",
  ui_story_5022_50220501_36_dialog_content = "...I will rectify this.",
  ui_story_5022_50220501_37_dialog_content = "(Her glare is more terrifying than some nine-headed dragon...)",
  ui_story_5022_50220501_38_dialog_content = "(Did something happen back then...?)",
  ui_story_5022_50220501_39_dialog_content = "Next, I have an important announcement! For real this time!",
  ui_story_5022_50220501_40_dialog_content = "First, we've confirmed the signal flares of contestants who have given up.",
  ui_story_5022_50220501_41_dialog_content = "The Lepidoz will soon reach the target location to pick up all you scaredy-cats, so just sit tight!",
  ui_story_5022_50220501_42_dialog_content = "What's more surprising is that this is the very first time we've had so few injuries this far into the race.",
  ui_story_5022_50220501_43_dialog_content = "Thus, let's spice things up by unveiling this year's mysterious prize...",
  ui_story_5022_50220501_44_dialog_content = "<size=45>\"Make a Wish to Eve\"!</size>",
  ui_story_5022_50220501_45_dialog_content = "What?",
  ui_story_5022_50220501_46_dialog_content = "That's right! Rediesel Wrench's Eve will make any wish of yours come true!",
  ui_story_5022_50220501_47_dialog_content = "Will the winner wish to see the lady's smile, or borrow the Necroid Dark Star's power?",
  ui_story_5022_50220501_48_dialog_content = "I'm looking forward to finding out!",
  ui_story_5022_50220501_49_dialog_content = "Eve didn't even let me know...",
  ui_story_5022_50220501_50_dialog_content = "You'd have objected, wouldn't you?",
  ui_story_5022_50220501_51_dialog_content = "Why would I?",
  ui_story_5022_50220501_52_dialog_content = "Seeing her fully recovered and willing to catch up on all the things she missed...",
  ui_story_5022_50220501_53_dialog_content = "And using her power to help everyone out... I couldn't be happier.",
  ui_story_5022_50220501_54_dialog_content = "Oh really? You know it's \"any wish,\" right?",
  ui_story_5022_50220501_55_dialog_content = "For example, what if someone wishes to marry her?",
  ui_story_5022_50220501_56_dialog_content = "...Hah?",
  ui_story_5022_50220501_57_option_content = "That's a possibility",
  ui_story_5022_50220501_58_dialog_content = "Eve is lovely and kind. Anyone would want to protect her.",
  ui_story_5022_50220501_59_dialog_content = "Anyone would be lucky to accompany her for the rest of their lives...",
  ui_story_5022_50220501_60_dialog_content = "What the heck are you thinking!?",
  ui_story_5022_50220501_61_dialog_content = "N-Nothing!",
  ui_story_5022_50220501_62_option_content = "I doubt it",
  ui_story_5022_50220501_63_dialog_content = "What? You don't think our Eve is good enough, is that it?",
  ui_story_5022_50220501_64_dialog_content = "Of course she is!",
  ui_story_5022_50220501_65_dialog_content = "If someone who would truly love her, treasure her, and protect her with their life really appeared...",
  ui_story_5022_50220501_66_dialog_content = "What to do? That little joke's got Sinsa all curled up in consternation!",
  ui_story_5022_50220501_67_dialog_content = "It's all your fault, PlayerName. Say something!",
  ui_story_5022_50220501_68_dialog_content = "My fault!?",
  ui_story_5022_50220501_69_dialog_content = "Hey, you! Out of the way! I'm going at full-speed here!",
  ui_story_5022_50220501_70_dialog_content = "Else I'll send you flying!",
  ui_story_5022_50220501_71_dialog_content = "Technically speaking, it's \"Brock is sitting in the car that Fleur is driving at full-speed.\"",
  ui_story_5022_50220501_72_dialog_content = "Hey, you're really gonna fall overboard if you keep leaning your body out the window like that!",
  ui_story_5022_50220501_73_dialog_content = "Oh boy, here comes trouble...",
  ui_story_5022_50220501_74_dialog_content = "Oooooohh! Isn't that PlayerName!?",
  ui_story_5022_50220501_75_dialog_content = "You're one step closer to becoming a hotblooded, virile young man by joining the Blazing Rally! But of course, you're still no match for me!",
  ui_story_5022_50220501_76_dialog_content = "Let me see... Your teammates are Joanie Boom and.... Miss Azure!?",
  ui_story_5022_50220501_77_dialog_content = "Long time no see, Brock. You seem like you've put on some meat since we last met.",
  ui_story_5022_50220501_78_dialog_content = "Gosh, you're still as beautiful as always...",
  ui_story_5022_50220501_79_dialog_content = "Ah, I mean o-of course! I'm already second-in-command of Rediesel Wrench!",
  ui_story_5022_50220501_80_dialog_content = "I'm the most popular man in Rediesel Wrench, but I still train every day! I never slack!",
  ui_story_5022_50220501_81_dialog_content = "Likewise, even if I'm going up against you in this rally, I shall still triumph and nab first place!",
  ui_story_5022_50220501_82_dialog_content = "After all, the grand prize was destined for me.",
  ui_story_5022_50220501_83_dialog_content = "The grand prize...?",
  ui_story_5022_50220501_84_dialog_content = "Sinsa?! What are you doing here?",
  ui_story_5022_50220501_85_dialog_content = "Is someone weaker than me capable of protecting my sister? Test... Right. I must test you.",
  ui_story_5022_50220501_86_dialog_content = "Why are you mumbling to yourself? Hmph, is it because I said I'm the second-in-command...?",
  ui_story_5022_50220501_87_dialog_content = "Why are you opening the door... Oh, come on! I shouldn't have bragged, but you don't have to be so upset!",
  ui_story_5022_50220501_88_dialog_content = "Miss Azure, what's that behind Brock and Fleur's car?",
  ui_story_5022_50220501_89_dialog_content = "Whatever! If you want a fight, I'll give you a fight!",
  ui_story_5022_50220501_90_dialog_content = "I'll beat you in our 873rd duel and eliminate your team in the process!",
  ui_story_5022_50220501_91_dialog_content = "Wait, it's not the time for a fight... Eclipsites incoming!",
  ui_story_5022_50220502_1_dialog_content = "Didn't we just defeat a wave of them? There are too many of them!",
  ui_story_5022_50220502_2_dialog_content = "Whoa! Look at the dust they kicked up! It's like a sandstorm!",
  ui_story_5022_50220502_3_dialog_content = "Even though the sand is partially obstructing my view, I can still feel Eclipsites gathering both in front of and behind us.",
  ui_story_5022_50220502_4_dialog_content = "Is that the special ability of your kind? Pretty neat, Caelestite.",
  ui_story_5022_50220502_5_dialog_content = "It doesn't seem like Sinsa and Brock are going to stop...",
  ui_story_5022_50220502_6_dialog_content = "Huh? When did they get on top of the car?",
  ui_story_5022_50220502_7_dialog_content = "Well obviously. No time is the wrong time for a fight among the Rediesel Wrench!",
  ui_story_5022_50220502_8_dialog_content = "Ha, hotblooded youth... They're never able to hold their horses.",
  ui_story_5022_50220502_9_dialog_content = "Perhaps I really should relax and have some fun...",
  ui_story_5022_50220502_10_dialog_content = "I'll deal with the Eclipsites at the back. Caelestite, take the wheel.",
  ui_story_5022_50220502_11_dialog_content = "Count me in! Come on, let's blow them sky-high!",
  ui_story_5022_50220502_12_dialog_content = "Me? But I don't know how to drive...",
  ui_story_5022_50220502_13_dialog_content = "Hey, don't let go of the wheel just like that!",
  ui_story_5022_50220502_14_dialog_content = "Heh, I can hardly wait. So where to begin?",
  ui_story_5022_50220502_15_dialog_content = "Let me ravage you all!",
  ui_story_5022_50220502_16_dialog_content = "Miss Azure, what should I...",
  ui_story_5022_50220502_17_dialog_content = "Hmm? Don't say you're done. We're just getting started.",
  ui_story_5022_50220502_18_dialog_content = "(Calm down... Calm down! There are guns and explosions going off but just calm down!)",
  ui_story_5022_50220502_19_dialog_content = "(Use your instinct, turn the wheel, and find a way to break through them...!)",
  ui_story_5022_50220502_20_dialog_content = "What are you waiting for, PlayerName! Hit the gas, let's go!",
  ui_story_5022_50220502_21_dialog_content = "Don't forget I'm a newbie! Which one's the throttle... this?!",
  ui_story_5022_50220502_22_dialog_content = "Fleur, let's throttle up too!",
  ui_story_5022_50220502_23_dialog_content = "Whoa. I came up to the roof just to look cool, but this really is high...",
  ui_story_5022_50220502_24_dialog_content = "The time is now!",
  ui_story_5022_50220502_25_dialog_content = "Brock, you better—",
  ui_story_5022_50220502_26_dialog_content = "—Behave!",
  ui_story_5022_50220502_27_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5022_50220502_28_dialog_content = "Oof...",
  ui_story_5022_50220502_29_dialog_content = "Hey, Brock, if you dodge, Powerball's hood will be dented.",
  ui_story_5022_50220502_30_dialog_content = "Poor little thing. It hurt, didn't it? I wonder if I have enough parts to repair you.",
  ui_story_5022_50220502_31_dialog_content = "Hello? I'm still here, you mechanic geek!",
  ui_story_5022_50220502_32_dialog_content = "And I didn't dodge! This is part of my strategy! Now I'm giving it all I've got!",
  ui_story_5022_50220502_33_dialog_content = "You must be fine if you're still able to holler like that.",
  ui_story_5022_50220502_34_dialog_content = "We've lost control of the car, we're headed straight for that boulder.",
  ui_story_5022_50220502_35_dialog_content = "Huh?",
  ui_story_5022_50220502_36_dialog_content = "Sinsa, mind lending a hand seeing as how you've decided to hitch a ride with us?",
  ui_story_5022_50220502_37_dialog_content = "We did it!",
  ui_story_5022_50220502_38_dialog_content = "There are no more Eclipsites after us... Did Azure take care of all those Eclipsites?!",
  ui_story_5022_50220502_39_dialog_content = "Hey, I helped! I want praise too!",
  ui_story_5022_50220502_40_dialog_content = "Just this isn't even anything worth gloating over. The weak don't last in the desert.",
  ui_story_5022_50220502_41_dialog_content = "However, you're more reliable than I expected, Caelestite. That was pretty good for a first time.",
  ui_story_5022_50220502_42_dialog_content = "Yup! Wanna consider signing up as a formal contestant next time...?",
  ui_story_5022_50220502_43_dialog_content = "Wait, if you're gonna compete anyway, why not go all in and challenge Azure's record?",
  ui_story_5022_50220502_44_option_content = "Now I'm interested",
  ui_story_5022_50220502_45_dialog_content = "Oh, how exciting. But you'll need more training to be a satisfying opponent for me.",
  ui_story_5022_50220502_46_dialog_content = "(She looks happy...)",
  ui_story_5022_50220502_47_option_content = "I'm not that good",
  ui_story_5022_50220502_48_dialog_content = "Shy, are we? As long as you're willing, I'm willing to teach you anything.",
  ui_story_5022_50220502_49_dialog_content = "(So close!)",
  ui_story_5022_50220502_50_dialog_content = "B-By the way, aren't we forgetting something?",
  ui_story_5022_50220502_51_dialog_content = "*Cough, cough*",
  ui_story_5022_50220502_52_dialog_content = "Although Sinsa managed to stop the car, it's gonna cost us a lot of time to fix all this damage.",
  ui_story_5022_50220502_53_dialog_content = "Wait, you're still not forfeiting? Your car is literally fuming.",
  ui_story_5022_50220502_54_dialog_content = "Don't ever underestimate a technician. I'm aiming to make giant mechs in the future. Fixing a car is nothing.",
  ui_story_5022_50220502_55_dialog_content = "Plus, the way you leaped over from the top of that car gave me new inspiration!",
  ui_story_5022_50220502_56_dialog_content = "Putting a vertical thruster system in the mecha might be a good idea...",
  ui_story_5022_50220502_57_dialog_content = "You really do like robots... To be honest though, that sounds pretty awesome.",
  ui_story_5022_50220502_58_dialog_content = "One more thing...",
  ui_story_5022_50220502_59_dialog_content = "What?",
  ui_story_5022_50220502_60_dialog_content = "Look over there.",
  ui_story_5022_50220502_61_dialog_content = "<size=45>Sinsa! We're leaving you behind if you don't get moving!</size>",
  ui_story_5022_50220502_62_dialog_content = "Hey! Wait up!",
  ui_story_5022_50220502_63_dialog_content = "Wow, he's running on foot and catching up to a running car. That's Sinsa for you!",
  ui_story_5022_50220502_64_dialog_content = "I'm the fastest man in Rediesel Wrench!",
  ui_story_5022_50220502_65_dialog_content = "And I will win the 874th duel to take the position of first-in-command!",
  ui_story_5022_50220502_66_dialog_content = "Next time I'll definitely get to show off in front of Miss Azure!",
  ui_story_5022_50220502_67_dialog_content = "Hahaha! That's the spirit!",
  ui_story_5022_50220502_68_dialog_content = "However, we're currently stranded in the middle of the desert, so...",
  ui_story_5022_50220502_69_dialog_content = "Hand me that green screwdriver, will you? Think of it as taking the first step in your next duel.",
  ui_story_5022_50220601_1_dialog_content = "Blowing up an opponent's ride... Is this what the Blazing Rally is supposed to be like? I wonder how the three of them are doing...",
  ui_story_5022_50220601_2_dialog_content = "Are you feeling a bit of the appeal of racing cars now?",
  ui_story_5022_50220601_3_dialog_content = "I thought this was all just some silly game for you and you weren't taking it so seriously...",
  ui_story_5022_50220601_4_dialog_content = "But you're clearly enjoying yourself!",
  ui_story_5022_50220601_5_dialog_content = "As a lady, I consider it etiquette to adapt to my suitors' ardor.",
  ui_story_5022_50220601_6_dialog_content = "You're right. This is a game, but it's not meant to be played.",
  ui_story_5022_50220601_7_dialog_content = "You seemed really into it while you were driving. You sure you don't want to keep going?",
  ui_story_5022_50220601_8_dialog_content = "Uh, well...",
  ui_story_5022_50220601_9_dialog_content = "Oh, come on, backing down already? You don't know how to party at all!",
  ui_story_5022_50220601_10_dialog_content = "However, even so, you're definitely gonna get hyped up soon. Heheh!",
  ui_story_5022_50220601_11_dialog_content = "...What do you mean?",
  ui_story_5022_50220601_12_dialog_content = "Because... phew, that was close. We're gonna reach the volcano stage next.",
  ui_story_5022_50220601_13_dialog_content = "Whoa!",
  ui_story_5022_50220601_14_dialog_content = "Oh, it's you, Sinsa. I thought a falling boulder had landed on the car. Do normal people enter cars by jumping through windows?",
  ui_story_5022_50220601_15_dialog_content = "Pfft, guess you caught up.",
  ui_story_5022_50220601_16_dialog_content = "Did you just scoff at me?",
  ui_story_5022_50220601_17_dialog_content = "I don't think Miss Azure meant to leave Sinsa behind...",
  ui_story_5022_50220601_18_dialog_content = "You're way too naive, she definitely was half-serious about it! Good thing I'm a fast runner!",
  ui_story_5022_50220601_19_dialog_content = "Wait, why do I feel the atmosphere getting heated?",
  ui_story_5022_50220601_20_dialog_content = "We've entered the second part of the rally, the <color=#FFB400>Dragon Breath Volcano</color>. We have to pass through this volcano.",
  ui_story_5022_50220601_21_dialog_content = "Are you kidding me? What kind of track is this!?",
  ui_story_5022_50220601_22_dialog_content = "Not going through the volcano is the shorter route to the Blazing Tooth, but...",
  ui_story_5022_50220601_23_dialog_content = "I wouldn't dream of not letting you have some fun when you've just learned the beauty of racing.",
  ui_story_5022_50220601_24_dialog_content = "We're pretty much comrades now, so you can have the wheel whenever you want to try.",
  ui_story_5022_50220601_25_dialog_content = "N-No, thanks! I still have ways to go!",
  ui_story_5022_50220601_26_dialog_content = "Don't be so humble, PlayerName.",
  ui_story_5022_50220601_27_dialog_content = "You're good at games and a natural at driving. Imagine that.",
  ui_story_5022_50220601_28_dialog_content = "(Oh, speaking of games...)",
  ui_story_5022_50220601_29_dialog_content = "(I wonder how Vice is doing.)",
  ui_story_5022_50220601_30_dialog_content = "(We were always together, experiencing all those wondrous and dangerous adventures with each other.)",
  ui_story_5022_50220601_31_dialog_content = "(...If only she were here.)",
  ui_story_5022_50220601_32_dialog_content = "Ackkkk! Stop, stop, stop! I'm sorry, Roy!",
  ui_story_5022_50220601_33_dialog_content = "I leave for five seconds and you decide to start running your mouth. Did you forget the additional clauses I mentioned so many times?",
  ui_story_5022_50220601_34_dialog_content = "Roy, come on! I only concealed part of the truth to better motivate them... Ouch! My ear!",
  ui_story_5022_50220601_35_dialog_content = "Sorry, guys. Let me clarify something: The host reserves the right to determine the parameters of the grand prize.",
  ui_story_5022_50220601_36_dialog_content = "Only one wish may be granted. If there are disagreements among the team, please resolve it among yourselves without resorting to violence.",
  ui_story_5022_50220601_37_dialog_content = "I hope you all do your best. May the best contestant win, and whoever that is, I recommend pondering carefully over what you want to wish for.",
  ui_story_5022_50220601_38_dialog_content = "And don't pull anything, because I'll break the legs of any cheaters myself. You all heard that?",
  ui_story_5022_50220601_39_dialog_content = "N-Now, let's catch everyone up on how the race is going.",
  ui_story_5022_50220601_40_dialog_content = "First we have Zeta, our Sweet Devil, the first one to reach the service station at the foot of the volcano.",
  ui_story_5022_50220601_41_dialog_content = "The status of the rest of the teams will soon follow after this short commercial—",
  ui_story_5022_50220601_42_dialog_content = "You want to savor something gourmet beneath the cherry blossoms...",
  ui_story_5022_50220601_43_dialog_content = "Diesel Sweety! Barbara! Woohoo!",
  ui_story_5022_50220601_44_dialog_content = "Huh, I'm hearing some background noise...",
  ui_story_5022_50220601_45_dialog_content = "♪ Blessings from me ride on fortuitous winds to you ♪",
  ui_story_5022_50220601_46_dialog_content = "Do you want to experience... the most supreme of tastes?",
  ui_story_5022_50220601_47_dialog_content = "♪ You wave your hand at me... I'm always here waiting... ♪",
  ui_story_5022_50220601_48_dialog_content = "Then come and try... Delicious! Kaniya Ramen!",
  ui_story_5022_50220601_49_dialog_content = "*Coughs* Darn it...",
  ui_story_5022_50220601_50_dialog_content = "♪ La la la! La la la! Sing it with me! ♪",
  ui_story_5022_50220601_51_dialog_content = "La la la! La la la!",
  ui_story_5022_50220601_52_dialog_content = "The music is overpowering the actual commercial...",
  ui_story_5022_50220601_53_dialog_content = "Ugh, fine. Diesel Sweety Barbara is hosting a 300-song concert in the convoy next to the Lepidoz...",
  ui_story_5022_50220601_54_dialog_content = "As one of the Logistics Team's entertainment staff, she...",
  ui_story_5022_50220601_55_dialog_content = "She doesn't care at all about how I nearly had my ears ripped off in the studio just now and she just starts singing at her scheduled time without a care in the world!",
  ui_story_5022_50220601_56_dialog_content = "Anyway, let's turn our attention to this great...",
  ui_story_5022_50220601_57_dialog_content = "It all ends now!",
  ui_story_5022_50220601_58_dialog_content = "Ugh... Regina? I didn't know she was gonna be here!",
  ui_story_5022_50220601_59_dialog_content = "Jomu, you really suck up to everyone.",
  ui_story_5022_50220601_60_dialog_content = "Neutrality is good for business. Mind putting that saw away?",
  ui_story_5022_50220601_61_dialog_content = "I won't let your horrific shrieks ruin everyone's ears, Barbara!",
  ui_story_5022_50220601_62_dialog_content = "I'll crush you with my searing music!",
  ui_story_5022_50220601_63_dialog_content = "Regina, you think I'm afraid of you?",
  ui_story_5022_50220601_64_dialog_content = "Barbara! Barbara!",
  ui_story_5022_50220601_65_dialog_content = "Solar Storm! Solar Storm!",
  ui_story_5022_50220601_66_dialog_content = "♪ La la la! Your luck, my luck! Let's hold hands! ♪",
  ui_story_5022_50220601_67_dialog_content = "Damn, she beat me to it! People, let's rock!",
  ui_story_5022_50220601_68_dialog_content = "♪ Roar! Roar! Who can save us from this impasse!? ♪",
  ui_story_5022_50220601_69_dialog_content = "Holy crap! Turn the station off! My brain is about to explode!",
  ui_story_5022_50220601_70_dialog_content = "Oh, is that all you can take, Caelestite?",
  ui_story_5022_50220601_71_dialog_content = "According to the customs of the Blazing Rally, the good stuff is yet to come.",
  ui_story_5022_50220601_72_dialog_content = "As the drivers race to edge each other out, Diesel Sweety and Solar Storm's duel reaches a climax!",
  ui_story_5022_50220601_73_dialog_content = "As you can hear, Diesel Sweety has chosen to go with a gleeful tune. Her sweet high notes can break wine glasses!",
  ui_story_5022_50220601_74_dialog_content = "As for Solar Storm, her song is reaching its hyped chorus!",
  ui_story_5022_50220601_75_dialog_content = "How will she choose to deliver those stimulating notes? Let's find out...",
  ui_story_5022_50220601_76_dialog_content = "So that's how! She's gonna... gonna...",
  ui_story_5022_50220601_77_dialog_content = "Solar Storm didn't smash the guitar for dramatic flair. Instead, she threw it down!",
  ui_story_5022_50220601_78_dialog_content = "Solar Storm has left the stage!",
  ui_story_5022_50220601_79_dialog_content = "Solar Storm... She's jumped into the prize she obtained from the Lumopolis pursuit! An airship!",
  ui_story_5022_50220601_80_dialog_content = "Solar Storm took the airship... and is going for the rock wall!",
  ui_story_5022_50220601_81_dialog_content = "Hmph! You little fried puff! <size=45>Have a taste of real music!</size>",
  ui_story_5022_50220601_82_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5022_50220601_83_dialog_content = "An explosion?!",
  ui_story_5022_50220601_84_dialog_content = "Where is the Lepidoz? It shouldn't affect us...",
  ui_story_5022_50220601_85_dialog_content = "<color=#e8d9bb>Ugh... Ah!</color>",
  ui_story_5022_50220601_86_dialog_content = "Well, I wouldn't be too confident about that.",
  ui_story_5022_50220601_87_dialog_content = "What's that sound?",
  ui_story_5022_50220601_88_dialog_content = "The... the cliff wall on the left is collapsing!",
  ui_story_5022_50220601_89_dialog_content = "Stay calm. Just stay ahead of the collapse and we'll be fine.",
  ui_story_5022_50220601_90_dialog_content = "Why are you scared? It's still safe on the right, isn't it?",
  ui_story_5022_50220601_91_dialog_content = "But we're already on full-throttle, and I can feel...",
  ui_story_5022_50220601_92_dialog_content = "It's filled with Eclipsites over there!",
  ui_story_5022_50220602_1_dialog_content = "Hey. You can open your eyes now. PlayerName?",
  ui_story_5022_50220602_2_dialog_content = "What should we do? Looks like you're a little shell-shocked.",
  ui_story_5022_50220602_3_dialog_content = "You're still too green. You'll get used to it when you experience it more.",
  ui_story_5022_50220602_4_dialog_content = "...No kidding!",
  ui_story_5022_50220602_5_dialog_content = "There we go! But we didn't do anything. What a medical miracle!",
  ui_story_5022_50220602_6_dialog_content = "More of this? It's a miracle I'm not dead!",
  ui_story_5022_50220602_7_dialog_content = "Something this minor is hardly a miracle.",
  ui_story_5022_50220602_8_dialog_content = "I'll explain, since I reserve some patience for cuties.",
  ui_story_5022_50220602_9_dialog_content = "Open your eyes and look at the road carefully. This side's the cliff, and that side's the rock wall.",
  ui_story_5022_50220602_10_dialog_content = "Right. I see.",
  ui_story_5022_50220602_11_dialog_content = "This place is near the edge of Eternal Night. The Eclipsites usually hide in the shadow of the rock wall to minimize energy costs.",
  ui_story_5022_50220602_12_dialog_content = "Ah, that makes sense.",
  ui_story_5022_50220602_13_dialog_content = "Which is to say, as long as we find the right angle, we can use Eclipsites as impact cushions.",
  ui_story_5022_50220602_14_dialog_content = "Now I understand...",
  ui_story_5022_50220602_15_dialog_content = "NOT!",
  ui_story_5022_50220602_16_dialog_content = "Using Eclipsites as cushions is beyond common sense!",
  ui_story_5022_50220602_17_dialog_content = "PlayerName, don't think. Feel, feel it with your heart.",
  ui_story_5022_50220602_18_dialog_content = "That's right! And trust Miss Azure, she's got this!",
  ui_story_5022_50220602_19_dialog_content = "Ugh... I'm the only one questioning things... This feels so bad...",
  ui_story_5022_50220602_20_dialog_content = "Vice...",
  ui_story_5022_50220602_21_dialog_content = "Vice... I need you here...",
  ui_story_5022_50220602_22_dialog_content = "(If only I had apologized to her back then...)",
  ui_story_5022_50220602_23_dialog_content = "<color=#e8d9bb>Rustle... Rustle...</color>",
  ui_story_5022_50220602_24_dialog_content = "Caelestite? Caelestite? Are you there?",
  ui_story_5022_50220602_25_dialog_content = "Again?!",
  ui_story_5022_50220602_26_dialog_content = "W-What happened to you? Did you eat something dirty from the ground? Or did the heat fry your brain?",
  ui_story_5022_50220602_27_dialog_content = "Um I mean... what's up, Zeta?",
  ui_story_5022_50220602_28_dialog_content = "What's up? You're slow. Too slow! Are you people even near the volcano yet?",
  ui_story_5022_50220602_29_dialog_content = "This isn't a worthy fight! It's one side obliterating the other!",
  ui_story_5022_50220602_30_dialog_content = "So I take it Miss Sweet Devil has already reached the finish line?",
  ui_story_5022_50220602_31_dialog_content = "Hehehe, I've already left the magma lake. Didn't expect that, did you!?",
  ui_story_5022_50220602_32_dialog_content = "I also obtained the Amulet of Frost to resist the heat from Tiny One, the weapons master of the warriors, at the service station!",
  ui_story_5022_50220602_33_dialog_content = "*Slurps*",
  ui_story_5022_50220602_34_dialog_content = "What is that sound...?",
  ui_story_5022_50220602_35_dialog_content = "Miss Sweet Devil is so impressive, it's got me positively trembling!",
  ui_story_5022_50220602_36_dialog_content = "Pretending that you don't care won't work. I'm a racer too, you can't fool me. You must be itching to catch up to me.",
  ui_story_5022_50220602_37_dialog_content = "Sadly, you've been out of the game for too long and you've lost your edge!",
  ui_story_5022_50220602_38_dialog_content = "More importantly, the fear of death and defeat has devoured you from the inside out!",
  ui_story_5022_50220602_39_dialog_content = "The racer in you has burnt away, not even ashes remain!",
  ui_story_5022_50220602_40_dialog_content = "I will be the one to defeat the wicked dragon. I shall be the champion of the race as well!",
  ui_story_5022_50220602_41_dialog_content = "Witness my victory!",
  ui_story_5022_50220602_42_dialog_content = "Awesome, I didn't stutter once and didn't skip any lines...!",
  ui_story_5022_50220602_43_dialog_content = "...You should check that your communications are switched off before breaking character...",
  ui_story_5022_50220602_44_dialog_content = "Huh, she must have practiced saying that before a mirror. The delivery was much smoother than her taunt the last time.",
  ui_story_5022_50220602_45_dialog_content = "Sinsa also raced against Zeta before?",
  ui_story_5022_50220602_46_dialog_content = "She got second place last time, and challenged me right on the stage.",
  ui_story_5022_50220602_47_dialog_content = "I didn't really understand what she was saying because she was having a meltdown.",
  ui_story_5022_50220602_48_dialog_content = "Fortunately for me, Roy pulled her off of me...",
  ui_story_5022_50220602_49_dialog_content = "Still, that was pretty brutal mocking... Even Azure didn't have a comeback.",
  ui_story_5022_50220602_50_dialog_content = "Miss Azure...?",
  ui_story_5022_50220602_51_dialog_content = "Solar Storm and Diesel Sweety's song battle has momentarily been put on pause.",
  ui_story_5022_50220602_52_dialog_content = "Now, let's turn our attention back to the race.",
  ui_story_5022_50220602_53_dialog_content = "I'm excited to announce that the contestants that reached the Dragon Breath Volcano, the second stage of the race...",
  ui_story_5022_50220602_54_dialog_content = "<size=45>Is few in numbers!</size>",
  ui_story_5022_50220602_55_dialog_content = "Okay, fine. That isn't something worth screeching about. What's really worth mentioning is that...",
  ui_story_5022_50220602_56_dialog_content = "Some contestants were so enticed by Kaniya Ramen's and Octobro Shaved Ice's commercials that they forfeited the game to satisfy their tummies!",
  ui_story_5022_50220602_57_dialog_content = "Oh, no need to be disappointed though!",
  ui_story_5022_50220602_58_dialog_content = "Past records indicate that only the best make it through the Hot Air Desert.",
  ui_story_5022_50220602_59_dialog_content = "Contestants have to navigate both the harsh environment and team cooperation, which are incredible challenges on their own.",
  ui_story_5022_50220602_60_dialog_content = "Do you still remember how we discovered this amazing route purely by accident because we got lost?",
  ui_story_5022_50220602_61_dialog_content = "I really thought I was gonna die during the search and rescue operation! Hahaha!",
  ui_story_5022_50220602_62_dialog_content = "I remember someone suggested using some scrap boards taken off the cars to slide down the magma fall...",
  ui_story_5022_50220602_63_dialog_content = "Magma fall!?",
  ui_story_5022_50220602_64_dialog_content = "Hmm... Nope. Can't remember. But there was also this one contestant who tried to freeze the entire Magma Lake...",
  ui_story_5022_50220602_65_dialog_content = "And a contestant who cut open an opponent's car into six pieces with a knife, but somehow the driver got out only with a bruised ego...",
  ui_story_5022_50220602_66_dialog_content = "Sadly, those two contestants used fake names and rarely participate.",
  ui_story_5022_50220602_67_dialog_content = "Oh, how we'd love to see them again, but I digress.",
  ui_story_5022_50220602_68_dialog_content = "We've also noticed an unusual increase in Eclipsites activity this time around.",
  ui_story_5022_50220602_69_dialog_content = "Regular Eclipsites don't pose a threat to our experienced racers...",
  ui_story_5022_50220602_70_dialog_content = "But! The Wicked Dragon Hakudoma is a different story!",
  ui_story_5022_50220602_71_dialog_content = "If it were to really show up, we should roll out some limited-edition Wicked Dragon souvenirs for profit!",
  ui_story_5022_50220602_72_dialog_content = "Why would anyone want that...?",
  ui_story_5022_50220602_73_dialog_content = "Odi from Logistics Team 3 is monitoring the current region through the pre-installed communications net on the Lepidoz.",
  ui_story_5022_50220602_74_dialog_content = "So far, there are no signs of large Eclipsites.",
  ui_story_5022_50220602_75_dialog_content = "How comforting, yet disappointing! Now, a short commercial break! Crunchy Munchy Crunch, one pack serves three meals...",
  ui_story_5022_50220602_76_dialog_content = "...No?",
  ui_story_5022_50220602_77_dialog_content = "(Why does Azure seem kind of... disappointed?)",
  ui_story_5022_50220602_78_dialog_content = "Miss Azure, are you hoping for Wicked Dragon Hakudoma to appear?",
  ui_story_5022_50220602_79_dialog_content = "Is it that obvious?",
  ui_story_5022_50220602_80_dialog_content = "Caelestite, you'd do well to not pick my brain.",
  ui_story_5022_50220602_81_dialog_content = "However, since you did pretty well when we were fighting against the other contestants... I'll humor you just this one time.",
  ui_story_5022_50220602_82_dialog_content = "This particular track means something special to me.",
  ui_story_5022_50220602_83_dialog_content = "It's here that I learned how to drive and participated in my first Blazing Rally, where I set new records time and time again.",
  ui_story_5022_50220602_84_dialog_content = "My best and worst memories live within this place.",
  ui_story_5022_50220602_85_dialog_content = "I experienced my worst failure here, and made an enemy that I vowed to kill.",
  ui_story_5022_50220602_86_dialog_content = "One day, I will crack its skull, crush its spine, and grind it to ash beneath my feet.",
  ui_story_5022_50220602_87_dialog_content = "I was hoping today would be the day.",
  ui_story_5022_50220602_88_dialog_content = "It can't just die and disappear before I have a chance to rip its guts out.",
  ui_story_5022_50220602_89_dialog_content = "What? Did I scare you?",
  ui_story_5022_50220602_90_dialog_content = "Rather...",
  ui_story_5022_50220602_91_dialog_content = "It's more that I finally see a glimpse of your true character.",
  ui_story_5022_50220602_92_dialog_content = "You may be dumb and cowardly, but you sure know how to please.",
  ui_story_5022_50220602_93_dialog_content = "How many hearts have you melted with those flowery words?",
  ui_story_5022_50220602_94_dialog_content = "I-I was just telling the truth...",
  ui_story_5022_50220602_95_dialog_content = "But, why are you so insistent on fighting this particular Eclipsite?",
  ui_story_5022_50220602_96_dialog_content = "You really do enjoy a story, don't you, Caelestite?",
  ui_story_5022_50220602_97_dialog_content = "I mean, it's been gone for over a decade.",
  ui_story_5022_50220602_98_dialog_content = "Maybe I should worry more about the crazy demands Zeta will make if she wins.",
  ui_story_5022_50220602_99_dialog_content = "She can do that? Is that a part of the duel?",
  ui_story_5022_50220602_100_dialog_content = "It's Zeta we're dealing with here. She's not gonna make it easy for you.",
  ui_story_5022_50220602_101_dialog_content = "Hey, Caelestite, don't say it like it's got nothing to do with you.",
  ui_story_5022_50220602_102_dialog_content = "We're teammates. Come what may, we'll face it all together, won't we?",
  ui_story_5022_50220602_103_dialog_content = "Huh?",
  ui_story_5022_50220602_104_dialog_content = "I think this is my stop right here...",
  ui_story_5022_50220602_105_dialog_content = [[
Ha. Don't start panicking yet.|
The game just started.]],
  ui_story_5022_50220802_1_dialog_content = "Finally, the maintenance station! I'm exhausted, all those Eclipsites were a real pain...",
  ui_story_5022_50220802_2_dialog_content = "Miss Azure, you're finally here! Park your car here, please...",
  ui_story_5022_50220802_3_dialog_content = "You, check for parts that need to be replaced!",
  ui_story_5022_50220802_4_dialog_content = "As for the tires... You! That's right, you! Get the tires out!",
  ui_story_5022_50220802_5_dialog_content = "And you lot, stop standing there eating jelly and get a move on!",
  ui_story_5022_50220802_6_dialog_content = "Yes, sir!",
  ui_story_5022_50220802_7_dialog_content = "Nicely done, Tiny One. You know how to get things done.",
  ui_story_5022_50220802_8_dialog_content = "Heheh.",
  ui_story_5022_50220802_9_dialog_content = "It's just a shame that your height doesn't match your authority...",
  ui_story_5022_50220802_9X1_dialog_content = "<size=45>Hey, hey! Stop that!</size>",
  ui_story_5022_50220802_10_dialog_content = "Why don't you stop commenting on my height and...",
  ui_story_5022_50220802_11_dialog_content = "Huh? PlayerName? Never thought I'd see you all the way out here.",
  ui_story_5022_50220802_12_dialog_content = "Someone as feeble as you making it this far... I'm impressed.",
  ui_story_5022_50220802_13_dialog_content = "That doesn't sound like a compliment...",
  ui_story_5022_50220802_14_dialog_content = "No, wait. What I meant to say was, you're too short to go around calling people feeble.",
  ui_story_5022_50220802_14X1_dialog_content = "<size=45>Hey! Cut it out!</size>",
  ui_story_5022_50220802_15_dialog_content = "Okay, that's enough of this. The Magma Lake Life Enders are coming up. Those bends are the hardest part of the track. Are you ready for them?",
  ui_story_5022_50220802_16_dialog_content = "Ouch! Wait... Why's it called Magma Lake?",
  ui_story_5022_50220802_17_dialog_content = "It's just what it sounds like. A lake of molten magma.",
  ui_story_5022_50220802_18_dialog_content = "I mean, that part was kind of obvious...",
  ui_story_5022_50220802_S18_dialog_content = "Okay, okay, I'm listening! Don't hit me!",
  ui_story_5022_50220802_19_dialog_content = "The temperature of the magma is high enough to vaporize you completely if you were to fall into it.",
  ui_story_5022_50220802_20_dialog_content = "The host did provide the contestants with equipment to combat the heat and toxic fumes, but you'll still feel like you're breathing fire.",
  ui_story_5022_50220802_21_dialog_content = "So... how do we get past it?",
  ui_story_5022_50220802_22_dialog_content = "Scared already? You really are hopeless... Here, take this bag of cactus jelly.",
  ui_story_5022_50220802_23_dialog_content = "So this can help me combat the heat? Desert plants are amazing...",
  ui_story_5022_50220802_24_dialog_content = "Nothing of the sort.",
  ui_story_5022_50220802_25_dialog_content = "Huh?",
  ui_story_5022_50220802_26_dialog_content = "It just tastes nice. That's all.",
  ui_story_5022_50220802_27_dialog_content = "Now, let's hear the reports from the teams!",
  ui_story_5022_50220802_28_dialog_content = "I wish I could call a commercial break, but we just don't have that many sponsors... I've even marketed my own products...",
  ui_story_5022_50220802_29_dialog_content = "*Slurps*",
  ui_story_5022_50220802_30_dialog_content = "Sweet Devil still has the lead. Azure, the runner-up, is still some distance away!",
  ui_story_5022_50220802_31_dialog_content = "Polar Fire, Team Kafka, and other eliminated contestants have been collected by the Lepidoz and are undergoing repairs.",
  ui_story_5022_50220802_32_dialog_content = "If I missed anyone, it's your own fault for being so difficult to find. Try harder!",
  ui_story_5022_50220802_33_dialog_content = "Spit out the blood and keep on going! I know you can do it! Don't stop!",
  ui_story_5022_50220802_34_dialog_content = "Setting an outstanding example for the rest of you, My Super Dream Team has been repaired by Fleur and is back into the game!",
  ui_story_5022_50220802_35_dialog_content = "If you can't repair your rides, please wait to be rescued by Chainsaw Rick and Rabbie!",
  ui_story_5022_50220802_36_dialog_content = "If nothing else, we can at lest help you dig out the wreckage from the sand, so you've got nothing to worry about!",
  ui_story_5022_50220802_37_dialog_content = "(Fine... It does taste nice. But it won't combat the heat and it's no Amulet of Frost...)",
  ui_story_5022_50220802_38_dialog_content = "Zeta is unstoppable in this race. She has demonstrated what a terrific driver she is.",
  ui_story_5022_50220802_39_dialog_content = "Her careful study and understanding of the Blazing Tooth has also helped her tremendously!",
  ui_story_5022_50220802_40_dialog_content = "(I'll bring some back as a souvenir for everyone back on the Colossus.)",
  ui_story_5022_50220802_41_dialog_content = "The result of this race seems set in stone... Huh? Miss Odi? What's wrong?",
  ui_story_5022_50220802_42_dialog_content = "<color=#e8d9bb>Rustle... Rustle...</color>",
  ui_story_5022_50220802_43_dialog_content = "This is Odi, overseer of communications in Logistics Team 3.",
  ui_story_5022_50220802_44_dialog_content = "Everyone, listen up.",
  ui_story_5022_50220802_45_dialog_content = "We've got trouble.",
  ui_story_5022_50220901_1_dialog_content = "We've detected a large number of Eclipsites between the Dragon Breath Volcano and Blazing Tooth.",
  ui_story_5022_50220901_2_dialog_content = "They're kicking up a lot of sand and dust, which is making them hard to track...",
  ui_story_5022_50220901_3_dialog_content = "But after checking the speed and size of one of them against historical records, we believe that we're dealing with a Dragon-type Eclipsite.",
  ui_story_5022_50220901_4_dialog_content = "It's moving along the track, but we're having difficulty contacting Zeta due to the sand and dust...",
  ui_story_5022_50220901_5_dialog_content = "I'll try to restore communications with the staff in the area. I'll keep you updated on any developments.",
  ui_story_5022_50220901_6_dialog_content = "Be careful out there, you oafs!",
  ui_story_5022_50220901_7_dialog_content = "It... It looks like we really have got ourselves a surprise visitor for the final stage of the rally!",
  ui_story_5022_50220901_8_dialog_content = "It's the legendary Eclipsite, the Wicked...",
  ui_story_5022_50220901_9_dialog_content = "This is an emergency! I'm taking over command!",
  ui_story_5022_50220901_10_dialog_content = "Currently, Zeta has only one path through the canyon in front of her. The Eclipsites will likely catch up to her.",
  ui_story_5022_50220901_11_dialog_content = "...!!",
  ui_story_5022_50220901_12_dialog_content = "She won't be able to handle them by herself. However, that kid is one of our best...",
  ui_story_5022_50220901_13_dialog_content = "So although she'll be terrified, she should be able to hold out for a bit.",
  ui_story_5022_50220901_14_dialog_content = "Logistics Team members in the Blazing Tooth area will be dispatched for immediate support.",
  ui_story_5022_50220901_15_dialog_content = "We'll need time to get there on regular vehicles. Azure, you're the closest contestant. We're counting on you.",
  ui_story_5022_50220901_16_dialog_content = "Once the Lepidoz reaches the communication area, I'll assign teams to take on the Eclipsites. Stand by for further orders.",
  ui_story_5022_50220901_17_dialog_content = "Roy sounds so calm... But the situation is bad, isn't it?",
  ui_story_5022_50220901_18_dialog_content = "Tiny One, can you calculate Zeta's position based on when she left the service station?",
  ui_story_5022_50220901_19_dialog_content = "Judging by the speed she was going at, she should be very close to the entrance of the canyon.",
  ui_story_5022_50220901_20_dialog_content = "It'll take a while to get there. Even you will have to slow down going through the Magma Lake Life Enders...",
  ui_story_5022_50220901_21_dialog_content = "Of course we won't make it in time via the regular route.",
  ui_story_5022_50220901_22_dialog_content = "Dammit, if only I'd followed my patrol route along the foot of the volcano instead of the track...",
  ui_story_5022_50220901_23_dialog_content = "Well, no time for remorse now...",
  ui_story_5022_50220901_24_dialog_content = "Caelestite, since you can see the flow of light, you can probably create a sensory network with multiple Aurorians, right? Like you did during the battle earlier?",
  ui_story_5022_50220901_25_dialog_content = "Sure... but I don't see how that'll help us get around Magma Lake...",
  ui_story_5022_50220901_26_dialog_content = "Oh, I think it will.",
  ui_story_5022_50220901_27_dialog_content = "I've found a route that'll knock your socks off.",
  ui_story_5022_50220901_28_dialog_content = "You ready, Caelestite?",
  ui_story_5022_50220901_S28_dialog_content = "I guess, but...",
  ui_story_5022_50220901_29_dialog_content = "How many times have I seen my life flash before my eyes now...?",
  ui_story_5022_50220901_30_dialog_content = "I'll go full throttle all the way to the top.",
  ui_story_5022_50220901_31_dialog_content = "Is there really no other way—Ahhhhhhhhh!",
  ui_story_5022_50220901_32_dialog_content = "<anim type=Shake><size=45>W-We're flying!</size></anim>",
  ui_story_5022_50220901_32X1_dialog_content = "(Jo-Jo-Jo-Joanie—)",
  ui_story_5022_50220901_33_dialog_content = "Sinsa, do you think she thought this through? Will it work?",
  ui_story_5022_50220901_34_dialog_content = "In theory, yes. The math is sound, but...",
  ui_story_5022_50220901_35_dialog_content = "Kicking bombs up into the air, shooting them, and using the explosions to propel the car across the Magma Lake?",
  ui_story_5022_50220901_36_dialog_content = "It's ludicrous by any standard!",
  ui_story_5022_50220901_37_dialog_content = "Hey, it's Azure and PlayerName we're talking about here. It'll work!",
  ui_story_5022_50220901_38_dialog_content = "There they are! Look over there, above Magma Lake! Sheesh, they're really high up, aren't they!",
  ui_story_5022_50220901_39_dialog_content = "Hehehe, this plan is so fun it can't possibly fail!",
  ui_story_5022_50220901_40_dialog_content = "Just because you're having fun doesn't mean you have to announce it to everyone!",
  ui_story_5022_50220901_41_dialog_content = "Stop glaring at me! If something were to happen to them, I'll be the first to come to their rescue!",
  ui_story_5022_50220901_42_dialog_content = "Wait! PlayerName is speaking to me telepathically!",
  ui_story_5022_50220901_43_dialog_content = "Batter, is the baseball... No, is the wrench ready? I'm gonna throw the bombs!",
  ui_story_5022_50220901_44_dialog_content = "I've got this!",
  ui_story_5022_50220901_45_dialog_content = "(Now Sinsa! Move it to the location I've marked—)",
  ui_story_5022_50220901_46_dialog_content = "Alright, bombs away!",
  ui_story_5022_50220901_47_dialog_content = "Incoming bomb, Azure! Ready—",
  ui_story_5022_50220901_47X1_dialog_content = "<size=45>Fire!!</size>",
  ui_story_5022_50220901_47X2_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5022_50220901_48_dialog_content = "<color=#e8d9bb>BOOM!</color>",
  ui_story_5022_50220901_49_dialog_content = "It worked! Just a few more times...",
  ui_story_5022_50220901_50_dialog_content = "(I have to keep the car balanced. If I move a bit to the right... Good!)",
  ui_story_5022_50220901_51_dialog_content = "(It's okay. Even if the worst were to happen...)",
  ui_story_5022_50220901_52_dialog_content = "Aaaah!",
  ui_story_5022_50220901_53_dialog_content = "PlayerName!",
  ui_story_5022_50220901_54_dialog_content = "(Don't look down... Don't look, don't look, don't look down!)",
  ui_story_5022_50220901_55_dialog_content = "Hey, if you really want to get away from me, I get it, but this isn't the best time.",
  ui_story_5022_50220901_56_dialog_content = "Or do you want me to let go?",
  ui_story_5022_50220901_57_dialog_content = "Stop teasing me, Azure... We're...",
  ui_story_5022_50220901_58_dialog_content = "Hm...? We're not actually falling all that fast...",
  ui_story_5022_50220901_59_dialog_content = "Do you see those floating magma rocks?",
  ui_story_5022_50220901_60_dialog_content = "The Dragon Breath Volcano is unique because objects that come close to it will hover a short distance above the ground.",
  ui_story_5022_50220901_61_dialog_content = "Whoa!",
  ui_story_5022_50220901_62_dialog_content = "Beautiful, isn't it? However, even though we've left our two passengers behind, we're still much heavier than those rocks.",
  ui_story_5022_50220901_63_dialog_content = "So, if you don't get back here and keep going...",
  ui_story_5022_50220901_64_dialog_content = "You should've said that earlier!",
  ui_story_5022_50220901_65_dialog_content = "Last strike!",
  ui_story_5022_50220901_66_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5022_50220901_67_dialog_content = "Oh! Did you see that! They've reached the other side of Magma Lake!",
  ui_story_5022_50220901_68_dialog_content = "They really did it. Now, that's a route past Magma Lake that hasn't been tried before...",
  ui_story_5022_50220901_69_dialog_content = "We don't have the time to think about that now! That High-Level Eclipsite...",
  ui_story_5022_50220901_70_dialog_content = "What are you talking about? The race isn't over yet!",
  ui_story_5022_50220901_71_dialog_content = "That's right. We just added a search and rescue mission wrapped in a boss challenge with a side of Eclipsite hunt!",
  ui_story_5022_50220901_72_dialog_content = "I wonder what that it'll be like to fight that dragon thingy... I'm getting excited just thinking about it!",
  ui_story_5022_50220901_73_dialog_content = "Tiny One! You need to get out of that workshop once in a while, or your brain's gonna rust!",
  ui_story_5022_50220901_74_dialog_content = "A party without surprise guests is no party at all!",
  ui_story_5022_50220901_75_dialog_content = "Hurry up, or all you're gonna get are leftovers!",
  ui_story_5022_50220901_76_dialog_content = "Well... We do have reserve vehicles in the service station...",
  ui_story_5022_50220901_77_dialog_content = "Count me in. Someone's gotta keep you from doing something stupid.",
  ui_story_5022_50220901_78_dialog_content = "Then, what are we waiting for!? Time to party!",
  ui_story_5022_50220901_79_dialog_content = "Destination: <color=#FFB400>Blazing Tooth</color>!",
  ui_story_5022_50221001_1_dialog_content = "Humph... I don't believe it... We actually did it!",
  ui_story_5022_50221001_2_dialog_content = "There's nothing that'll surprise me any—",
  ui_story_5022_50221001_3_dialog_content = "No, better not jinx it... I'm still here with the Rediesel Wrench.",
  ui_story_5022_50221001_4_dialog_content = "See? You're learning, PlayerName.",
  ui_story_5022_50221001_5_dialog_content = "(Did Miss Azure just... use my name?)",
  ui_story_5022_50221001_6_dialog_content = "(That said, when she grabbed me above Magma Lake, she also...)",
  ui_story_5022_50221001_7_dialog_content = "Why are you smiling?",
  ui_story_5022_50221001_8_dialog_content = "N-Nothing! I was just thinking that there's no way Sinsa can compete with you when you're going all out!",
  ui_story_5022_50221001_9_dialog_content = "Well, you're wrong. Sinsa stopped my Colossus once using just one hand. That was something.",
  ui_story_5022_50221001_10_dialog_content = "I don't know how to put it but... I'd say you're a proper Rediesel Wrench vet.",
  ui_story_5022_50221001_11_dialog_content = "I'll take that as a compliment. This race may get a little crazy at times, but it sure is addictive, isn't it!?",
  ui_story_5022_50221001_12_dialog_content = "Speaking of, you're a bit of a madman yourself.",
  ui_story_5022_50221001_13_dialog_content = "Back there, you counted on me to hold onto you while you tried to balance the car out, right?",
  ui_story_5022_50221001_14_dialog_content = "Well, that wasn't the safest bet. I'm not a team player. What if I hadn't reached for you?",
  ui_story_5022_50221001_15_dialog_content = "You would have.",
  ui_story_5022_50221001_16_dialog_content = "I'm used to giving out orders in a battle, so I know these things.",
  ui_story_5022_50221001_17_dialog_content = "Even though you complain about people getting in your way, you always pay attention to your teammates and know exactly what they're doing.",
  ui_story_5022_50221001_18_dialog_content = "You don't miss a thing.",
  ui_story_5022_50221001_19_dialog_content = "You flatter me, PlayerName. I like it.",
  ui_story_5022_50221001_20_dialog_content = "Huh, how about that. I guess I'm really kind of into you now.",
  ui_story_5022_50221001_21_dialog_content = "Oh, err...",
  ui_story_5022_50221001_22_dialog_content = "...",
  ui_story_5022_50221001_23_dialog_content = "There's still a way to go before we reach the canyon's entrance. Time for a story.",
  ui_story_5022_50221001_24_dialog_content = "You're curious about what happened between me and that Eclipsite, right? It's written all over your face.",
  ui_story_5022_50221001_25_dialog_content = "...",
  ui_story_5022_50221001_26_dialog_content = "It defeated me. I didn't stand a chance against it...",
  ui_story_5022_50221001_27_dialog_content = "If Roy hadn't gotten there when he did, I wouldn't be here right now.",
  ui_story_5022_50221001_28_dialog_content = "...!",
  ui_story_5022_50221001_29_dialog_content = "Even though he jokes about it all the time and tells the story to the kids as a fairy tale...",
  ui_story_5022_50221001_30_dialog_content = "We both know, what happened that day scarred us forever.",
  ui_story_5022_50221001_31_dialog_content = "It's hard to imagine, right? The Rediesel Wrench barely escaped from an Eclipsite ambush just over a decade ago.",
  ui_story_5022_50221001_32_dialog_content = "Mobs of monsters tried to circle around Illumina's defense lines through the desert... That Eclipsite was one of them.",
  ui_story_5022_50221001_33_dialog_content = "I lost my home and many of my friends in those battles.",
  ui_story_5022_50221001_34_dialog_content = "After that, I gave up racing cars.",
  ui_story_5022_50221001_35_dialog_content = "Training for battle and for survival just seemed more important than games.",
  ui_story_5022_50221001_36_dialog_content = "I've always been a lone wolf because I'm not confident in my ability to look after my comrades.",
  ui_story_5022_50221001_37_dialog_content = "Pathetic, isn't it? But I don't want to feel that... helplessness ever again.",
  ui_story_5022_50221001_38_dialog_content = "Azure...",
  ui_story_5022_50221001_39_dialog_content = "Even though I've accomplished one dangerous exploration after another, I still worry that I'm not good enough.",
  ui_story_5022_50221001_40_dialog_content = "Am I good enough to fight off our enemies and protect the people who matter the most to me?",
  ui_story_5022_50221001_41_dialog_content = "If I meet my old nemesis again, will it really turn out any different?",
  ui_story_5022_50221001_42_dialog_content = "Just like the rally, even though I've said I've given up on it...",
  ui_story_5022_50221001_43_dialog_content = "I still finish my missions early just to sneak back and watch it every time...",
  ui_story_5022_50221001_44_dialog_content = "I'm not as reliable and capable as you think I am. I'm just a...",
  ui_story_5022_50221001_45_dialog_content = "Just an amateur.",
  ui_story_5022_50221001_46_dialog_content = "You're nothing of the sort.",
  ui_story_5022_50221001_47_dialog_content = "There's nothing wrong with enjoying what you love.",
  ui_story_5022_50221001_48_dialog_content = "This might sound weird coming from an outsider, but...",
  ui_story_5022_50221001_49_dialog_content = "Isn't Rediesel Wrench's principle to live life to the fullest?",
  ui_story_5022_50221001_50_dialog_content = "All the Rediesel members I know would treat any danger as a chance to have fun.",
  ui_story_5022_50221001_51_dialog_content = "Now that you say it... I can almost see Joanie's face beaming with excitement.",
  ui_story_5022_50221001_52_dialog_content = "And just like how my friends and I rely on each other, the Rediesel Wrench would never let you face your nemesis alone.",
  ui_story_5022_50221001_53_dialog_content = "I mean... Obviously right now it's just me, but...",
  ui_story_5022_50221001_54_dialog_content = "I'll help you in any way I can, even though I don't know how to use Luminatics.",
  ui_story_5022_50221001_55_dialog_content = "So, in the upcoming battles, you can rely on me!",
  ui_story_5022_50221001_56_dialog_content = "PlayerName...",
  ui_story_5022_50221001_57_dialog_content = "Now I feel embarrassed that I blabbered on about my past...",
  ui_story_5022_50221001_58_dialog_content = "But... I knew I had my eye on you for a reason. You're a good man.",
  ui_story_5022_50221001_59_dialog_content = "We're almost at the entrance to the canyon. Zeta is probably crying like a baby right now.",
  ui_story_5022_50221001_60_dialog_content = "By the way... Roy even pretended to be a princess for Zeta's stories...",
  ui_story_5022_50221001_61_dialog_content = "But when she's in mortal danger, he believes she can hold her own until we get there?",
  ui_story_5022_50221001_62_dialog_content = "Rediesel Wrench sure offers a wild kind of education...",
  ui_story_5022_50221001_63_dialog_content = "It's like he said, Zeta is one of our best.",
  ui_story_5022_50221001_64_dialog_content = "But we still shouldn't make her wait too long. We'd better take out these Eclipsites and get a move on.",
  ui_story_5022_50221001_65_dialog_content = "Let's show them what we've got, PlayerName!",
  ui_story_5022_50221101_1_dialog_content = "See that black mass of Eclipsites?",
  ui_story_5022_50221101_2_dialog_content = "Eww... They move like worms when they're stuffed together like that. Disgusting...",
  ui_story_5022_50221101_3_dialog_content = "Let's blow them sky-high! I was looking for a chance to calibrate my new bombs. But, the wicked dragon is mine!",
  ui_story_5022_50221101_4_dialog_content = "No worries. That High-Level Eclipsite is not among them.",
  ui_story_5022_50221101_5_dialog_content = "It must have followed Zeta into the canyon. It's surprisingly fast...",
  ui_story_5022_50221101_6_dialog_content = "The rest of the Eclipsites seem to be moving toward the center.",
  ui_story_5022_50221101_7_dialog_content = "Are they trying to slow down Miss Azure? It's too far away to tell...",
  ui_story_5022_50221101_8_dialog_content = "<color=#e8d9bb>Crackle... Crackle...</color>",
  ui_story_5022_50221101_9_dialog_content = "Tiny One, can you hear me?",
  ui_story_5022_50221101_10_dialog_content = "Roy! I hear you! Honcho Sinsa and Joanie Boom are also here with me. What do you need?",
  ui_story_5022_50221101_11_dialog_content = "Sinsa? Shouldn't he be with Azure...?",
  ui_story_5022_50221101_12_dialog_content = "Never mind. It's better this way... You can wreck some serious havoc this way.",
  ui_story_5022_50221101_13_dialog_content = "Move up behind them, then get their attention and rip them apart. We need to give Azure a chance to break through.",
  ui_story_5022_50221101_14_dialog_content = "How's that for a plan, leader?",
  ui_story_5022_50221101_15_dialog_content = "We'll let Azure be the hero this time... She can have this party - but just this one!",
  ui_story_5022_50221101_16_dialog_content = "I know you've heard this already, and there's probably nothing to worry about with the leader being here... But I'd like to remind you...",
  ui_story_5022_50221101_17_dialog_content = "Eliminate those watermelon worms first to prevent spikes. Protect our ride!",
  ui_story_5022_50221101_18_dialog_content = "And get rid of those annoying hairy mops that can heal other Eclipsites as well! Finish them all!",
  ui_story_5022_50221101_19_dialog_content = "Those Eyeball Monsters that look like poorly boiled eggs can be a real pain, because they keep summoning minions. Destroy them as soon as you can. Got it?",
  ui_story_5022_50221101_20_dialog_content = "Err... What else...",
  ui_story_5022_50221101_21_dialog_content = "Keep your distance from Mega Fists. And be extra cautious with the Flying Octopuses—they'll try to throw us out of sync.",
  ui_story_5022_50221101_22_dialog_content = "... Roy, did you just sigh? Correct me if I said anything wrong.",
  ui_story_5022_50221101_23_dialog_content = "No no, you're doing a fabulous job. It's just... It's incredible how fast the kids grow up...",
  ui_story_5022_50221101_24_dialog_content = [[
Kafka and Sork will join you shortly. Take charge of the battle, leader. |
Have fun.]],
  ui_story_5022_50221101_25_dialog_content = "Aaaaaahhh! Screw you, Barbara, you ruined my solo concert again!",
  ui_story_5022_50221101_26_dialog_content = "Graaaah!!",
  ui_story_5022_50221101_27_dialog_content = "Shut up! Fall down and stay down! Solo Requiem!",
  ui_story_5022_50221101_28_dialog_content = "Oh? Your concert, is it? Excuse me, but I think everyone's here for me!",
  ui_story_5022_50221101_29_dialog_content = "Ready? Sweet Kiss!",
  ui_story_5022_50221101_30_dialog_content = "Oh, really? Who on earth actually likes your stupid love songs?",
  ui_story_5022_50221101_31_dialog_content = "I'd say your relentless shrieking is slightly harder on the ears.",
  ui_story_5022_50221101_32_dialog_content = "Are you looking for a fight?",
  ui_story_5022_50221101_33_dialog_content = "If that's what you want, I wouldn't have the heart to say no!",
  ui_story_5022_50221101_34_dialog_content = "*Cough* Sorry to interrupt.",
  ui_story_5022_50221101_35_dialog_content = "You two split up with Lepidoz and circled around the volcano to attack through the northern desert. You must be coming up on the Eclipsites, right?",
  ui_story_5022_50221101_36_dialog_content = "You're too slow, Roy. We've been in action for a while. We're supposed to scorch them all, right?",
  ui_story_5022_50221101_37_dialog_content = "Psh... They're all small fry, it's boring.",
  ui_story_5022_50221101_38_dialog_content = "Once in a blue moon, I agree with you.",
  ui_story_5022_50221101_39_dialog_content = "But I'll complete any mission I'm given, no matter how trivial. Super idols have superior work ethics!",
  ui_story_5022_50221101_40_dialog_content = "Well I'm sorry, but holding the enemy in check and preventing more Eclipsites from flooding into the canyon really is an important task.",
  ui_story_5022_50221101_41_dialog_content = "Hey, how does this sound? Whoever destroys more Eclipsites can have a solo performance at the next Fiery Support concert.",
  ui_story_5022_50221101_42_dialog_content = "!!!",
  ui_story_5022_50221101_43_dialog_content = "And the singer gets to choose any venue, even Lepidoz or the Oasis.",
  ui_story_5022_50221101_44_dialog_content = "Wooh! Are you sure about this?",
  ui_story_5022_50221101_45_dialog_content = "If I choose the Oasis, I can use fantastic, dreamy light effects! I'm getting excited just thinking about it...",
  ui_story_5022_50221101_46_dialog_content = "Wait, but a concert on a moving Lepidoz is also a rare opportunity...",
  ui_story_5022_50221101_47_dialog_content = "Hey! Regina! Don't you jump the gun!",
  ui_story_5022_50221101_48_dialog_content = "Phew... Now, what's next...",
  ui_story_5022_50221101_49_dialog_content = "Azure, the Eclipsites are beginning to disperse. We'll be able to break out soon!",
  ui_story_5022_50221101_50_dialog_content = "Did help come from the Rediesel Wrench?",
  ui_story_5022_50221101_51_dialog_content = "Eclipsites wouldn't lose interest in us just like that. For the enemy to disperse this fast... this has to be Roy's work.",
  ui_story_5022_50221101_52_dialog_content = "Um, looks like we have an incoming message.",
  ui_story_5022_50221101_53_dialog_content = "Hello...?",
  ui_story_5022_50221101_54_dialog_content = "Bye.",
  ui_story_5022_50221101_55_dialog_content = "Wha...?",
  ui_story_5022_50221101_56_dialog_content = "Hold on! Now, that's cold. The mother hen in me is devastated!",
  ui_story_5022_50221101_57_dialog_content = "Come on, you're too old for that. Have some self respect.",
  ui_story_5022_50221101_58_dialog_content = "Cough... Right. So...",
  ui_story_5022_50221101_59_dialog_content = "... Roy.",
  ui_story_5022_50221101_60_dialog_content = "I know what you're going to say. Don't worry, I've already seen it myself.",
  ui_story_5022_50221101_61_dialog_content = "The Rediesel Wrench used to fear the Eclipsites because it was defeated by them. But over the past decade, it has changed...",
  ui_story_5022_50221101_62_dialog_content = "And so have I.",
  ui_story_5022_50221101_63_dialog_content = "Right?",
  ui_story_5022_50221101_64_dialog_content = "Azure...",
  ui_story_5022_50221101_65_dialog_content = "The only way I can get out from the haunting shadow of the past, is by finishing this myself.",
  ui_story_5022_50221101_66_dialog_content = "So if you have anything to say, save it for my triumphant return.",
  ui_story_5022_50221101_67_dialog_content = "... I see. Well, we've opened a path for you.",
  ui_story_5022_50221101_68_dialog_content = "Happy hunting.",
  ui_story_5022_50221201_1_dialog_content = "<color=#e8d9bb>Over ten years ago</color>",
  ui_story_5022_50221201_2_dialog_content = "Gaar...",
  ui_story_5022_50221201_3_dialog_content = "Huff... Wheeze... There's no end of this...",
  ui_story_5022_50221201_4_dialog_content = "Ghaaar...",
  ui_story_5022_50221201_5_dialog_content = "Looks like that jerk is planning to wear me out before it makes its move...",
  ui_story_5022_50221201_6_dialog_content = "(Drawing it away using the car clearly isn't going to work... But if I fail, then everyone will...)",
  ui_story_5022_50221201_7_dialog_content = "... What? Say that again!",
  ui_story_5022_50221201_8_dialog_content = "You heard me alright.",
  ui_story_5022_50221201_9_dialog_content = "What do you mean the leader isn't coming, Roy? Look at me!",
  ui_story_5022_50221201_10_dialog_content = "The crisis is far from over. They can buy us some time with their lives, but those Eclipsites who destroyed our base will soon catch up.",
  ui_story_5022_50221201_11_dialog_content = "One of the Eclipsites looks like a dragon. It moves extremely fast. I'll try to draw it away. Sinsa, take...",
  ui_story_5022_50221201_12_dialog_content = "Why did you come back alone? Why...",
  ui_story_5022_50221201_13_dialog_content = "I also wish I was the one who died, Azure.",
  ui_story_5022_50221201_14_dialog_content = "Once we get through this, you can hit me as hard as you like. But right now... Hey! Where are you going?",
  ui_story_5022_50221201_15_dialog_content = "(I said some pretty cruel things to him back then. I hope I get the chance to apologize...)",
  ui_story_5022_50221201_16_dialog_content = "(I should be able to shoot from behind this cover...)",
  ui_story_5022_50221201_17_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5022_50221201_18_dialog_content = "Ahh...!",
  ui_story_5022_50221201_19_dialog_content = "(Shit... It didn't even penetrate the outer skin!)",
  ui_story_5022_50221201_20_dialog_content = "(The gun... I need to get my gun back...)",
  ui_story_5022_50221201_21_dialog_content = "Gah... It really hurts...",
  ui_story_5022_50221201_22_dialog_content = "(I can't... move...)",
  ui_story_5022_50221201_23_dialog_content = "(Did I break a bone when I hit the rock earlier? Or did his roar somehow numb my nerves?)",
  ui_story_5022_50221201_24_dialog_content = "(Focus on the present. I can't give up just yet... I can't...)",
  ui_story_5022_50221201_25_dialog_content = "<anim type=Shake><size=45>Roar!</size></anim>",
  ui_story_5022_50221201_26_dialog_content = "(No... My consciousness... Is fading...)",
  ui_story_5022_50221201_27_dialog_content = "(Did the others manage to escape?)",
  ui_story_5022_50221201_28_dialog_content = "(Am I going to die here?)",
  ui_story_5022_50221201_29_dialog_content = "<color=#e8d9bb>*Rumble*</color>",
  ui_story_5022_50221201_30_dialog_content = "<size=45>Gaar, ahhhhhh!</size>",
  ui_story_5022_50221201_31_dialog_content = "(Was that... an explosion?)",
  ui_story_5022_50221201_32_dialog_content = "Cough... Ah-hahah... Looks like... I made it just in time.",
  ui_story_5022_50221201_33_dialog_content = "Roy! You...",
  ui_story_5022_50221201_34_dialog_content = "What's with that face? I thought... Hngh... I thought you'd be happier to see me.",
  ui_story_5022_50221201_35_dialog_content = "The situation is currently under control, but our firepower can't keep the enemy down for long...",
  ui_story_5022_50221201_36_dialog_content = "Ah... You're... *Cough* Worried about this...",
  ui_story_5022_50221201_37_dialog_content = "Ouch... I didn't think it had enough strength left to attack you...",
  ui_story_5022_50221201_38_dialog_content = "Yeah, it does hurt a little... But it's nothing that a good night's sleep won't fix...",
  ui_story_5022_50221201_39_dialog_content = "I've got my share of flaws... But physical weakness isn't one of them.",
  ui_story_5022_50221201_40_dialog_content = "Shut up. If you keep talking, your wound...",
  ui_story_5022_50221201_41_dialog_content = "The others have... Reached safety. There was some kind of giant lizard...",
  ui_story_5022_50221201_42_dialog_content = "But I sent Sinsa to check it out... So, don't worry...",
  ui_story_5022_50221201_43_dialog_content = "Give me a few more seconds... Let me recover some strength...",
  ui_story_5022_50221201_44_dialog_content = "I can freeze the claw. It'll become brittle so I can break it off!",
  ui_story_5022_50221201_45_dialog_content = "... You always come up with a plan.",
  ui_story_5022_50221201_46_dialog_content = "Unlike me, charging straight ahead with no brains and ending up like this... The leader's definitely going to scold me for this...",
  ui_story_5022_50221201_47_dialog_content = "...",
  ui_story_5022_50221201_48_dialog_content = "Oh... No... She won't... I almost forgot... She's already gone...",
  ui_story_5022_50221201_49_dialog_content = "Since neither the Eclipsite nor we can move at the moment, I... *cough*... I must vent a little.",
  ui_story_5022_50221201_50_dialog_content = "Do you really think this is a good time for preaching?",
  ui_story_5022_50221201_51_dialog_content = "There won't be any preaching. But how many times have I told you not to go off on your own and try to prove how brave you are?",
  ui_story_5022_50221201_52_dialog_content = "I've taught you too well. I couldn't catch up with you in a car if I tried... I'll need to practice more...",
  ui_story_5022_50221201_53_dialog_content = "The leader... She made me promise to keep you and the Rediesel Wrench safe. That guy sure loved to boss people around...",
  ui_story_5022_50221201_54_dialog_content = "She told me... Heh... That I had to keep my promise for a hundred years.",
  ui_story_5022_50221201_55_dialog_content = "It hurts my head just thinking about turning this group of idiots and roaming bandits into masters of the desert.",
  ui_story_5022_50221201_56_dialog_content = "Sure, they were her dying words, but... she's asking for a lot.",
  ui_story_5022_50221201_57_dialog_content = "So... I'm going to need you to stick around.",
  ui_story_5022_50221201_58_dialog_content = "We've got too much on our plate to die here.",
  ui_story_5022_50221201_59_dialog_content = "You don't have to tell me that! Now shut up, I need to focus to control the range of my Luminatics.",
  ui_story_5022_50221201_60_dialog_content = "Hahah. *cough*... Sounds like someone has rested enough.",
  ui_story_5022_50221201_61_dialog_content = "Let's... Go home.",
  ui_story_5022_50221201_62_dialog_content = "We'll build a new stronghold... Somewhere with water and lots of trees...",
  ui_story_5022_50221202_1_dialog_content = "Err... Miss Azure?",
  ui_story_5022_50221202_2_dialog_content = "Nothing a good night's sleep won't fix... Hah, he was out for over a week straight...",
  ui_story_5022_50221202_3_dialog_content = "Who exactly was trying to be brave?",
  ui_story_5022_50221202_4_dialog_content = "... Miss Azure? Miss Azure?",
  ui_story_5022_50221202_5_dialog_content = "What was that?",
  ui_story_5022_50221202_6_dialog_content = "You seem distant. And you've been murmuring to yourself while speeding up... Are you okay?",
  ui_story_5022_50221202_7_dialog_content = "I just... Remembered something from the past.",
  ui_story_5022_50221202_8_dialog_content = "Don't worry. I could drive this track with my eyes closed.",
  ui_story_5022_50221202_8X_dialog_content = "I'd prefer it if you kept them open...",
  ui_story_5022_50221202_9_dialog_content = "I can feel that High-Level Eclipsite. It's very close to us.",
  ui_story_5022_50221202_10_dialog_content = "Its Darkflow feels familiar. In a very unsettling way...",
  ui_story_5022_50221202_11_dialog_content = "We've entered the canyon. The sand won't affect our comms equipment as much here... We might be able to reach Zeta...",
  ui_story_5022_50221202_12_dialog_content = "<color=#e8d9bb>Crackle... Crackle...</color>",
  ui_story_5022_50221202_13_dialog_content = "Boo-hoo... Ahhhhhh!",
  ui_story_5022_50221202_14_dialog_content = "Is anyone there? I need help...",
  ui_story_5022_50221202_15_dialog_content = "Zeta! Thank goodness. Are you okay?",
  ui_story_5022_50221202_16_dialog_content = "The communication is back up? Caelestite! Is that you?",
  ui_story_5022_50221202_17_dialog_content = "I, I...",
  ui_story_5022_50221202_18_dialog_content = "I'm sowwy! Wahhh!",
  ui_story_5022_50221202_19_dialog_content = "That's... very loud.",
  ui_story_5022_50221202_20_dialog_content = "I'm sorry! I wanted... *Sniff*... I wanted to make friends with everyone.",
  ui_story_5022_50221202_21_dialog_content = "I wanted to play with the others... I *sob* I only made trouble *sniff* so that people would notice me...",
  ui_story_5022_50221202_22_dialog_content = "Waaah! Sorry, Maggie... We're on the same team but I pulled so many pranks on you...",
  ui_story_5022_50221202_23_dialog_content = "And... And Tiny One, Kafka, Rabbie, Odi, Jomu, Clover, Chainsaw Rick, and Sork...",
  ui_story_5022_50221202_24_option_content = "You wanna apologize to all those people?",
  ui_story_5022_50221202_25_dialog_content = "I'm not done yet! There are many more in the Rediesel Wrench...",
  ui_story_5022_50221202_26_dialog_content = "Like the Scorching Jinx, Tempest Emperor, Dusk Phoenix, Fallen Warwraith... Waaah...",
  ui_story_5022_50221202_27_dialog_content = "(I've never even heard of those people...)",
  ui_story_5022_50221202_28_option_content = "Zeta, calm down for a minute...",
  ui_story_5022_50221202_29_dialog_content = "No!",
  ui_story_5022_50221202_30_dialog_content = "(I guess I'll let her finish...)",
  ui_story_5022_50221202_31_dialog_content = "*Sob*... Azure...",
  ui_story_5022_50221202_32_dialog_content = "Go ahead. I'm listening.",
  ui_story_5022_50221202_33_dialog_content = "The, the only reason I keep making trouble for you is because I'm jealous.",
  ui_story_5022_50221202_34_dialog_content = "You're so good at everything. And Roy trusts you more than anyone else...",
  ui_story_5022_50221202_35_dialog_content = "That's why I always try to find flaws with you...",
  ui_story_5022_50221202_36_dialog_content = "Under my bed there's a tin box. It contains all the candies I've collected over the years.",
  ui_story_5022_50221202_37_dialog_content = "Azure... *Sniff*... You take it and share it with everyone...",
  ui_story_5022_50221202_38_dialog_content = "Got it. Anything else?",
  ui_story_5022_50221202_39_dialog_content = "*Sniff* It's booby trapped, so be very careful when, when you remove it...",
  ui_story_5022_50221202_40_dialog_content = "Give some extra candies to Maggie in the Canary. And Roy because he always works so late. And...",
  ui_story_5022_50221202_41_dialog_content = "Please tell everyone I love them... Waaah...",
  ui_story_5022_50221202_42_dialog_content = "It's been sixteen beautiful years in the Rediesel Wrench...",
  ui_story_5022_50221202_43_dialog_content = "Please don't forget me... Waaaaahhh!",
  ui_story_5022_50221202_44_dialog_content = "Are you done?",
  ui_story_5022_50221202_45_dialog_content = "Yeah...",
  ui_story_5022_50221202_46_dialog_content = "I won't do it.",
  ui_story_5022_50221202_47_dialog_content = "Huh?",
  ui_story_5022_50221202_48_dialog_content = "All those requests, they're too much trouble. I don't have time for this. Better you do it yourself.",
  ui_story_5022_50221202_49_dialog_content = "But...",
  ui_story_5022_50221202_50_dialog_content = "Don't worry. I'll be the hero...",
  ui_story_5022_50221202_51_dialog_content = "Actually, I'll be the villain who, touched by the noble ways of the hero, abandons her evil ways and returns to the path of virtue...",
  ui_story_5022_50221202_52_dialog_content = "Then when the hero faces insurmountable odds, she jumps out and defeats the dragon.",
  ui_story_5022_50221202_53_dialog_content = "... I'll bring you home, Zeta.",
  ui_story_5022_50221301_1_dialog_content = "Azure, I see it! Over there!",
  ui_story_5022_50221301_2_dialog_content = "(That High-Level Eclipsite looks like a modified Nozard...)",
  ui_story_5022_50221301_3_dialog_content = "PlayerName, sit tight. I'm about to step on the gas.",
  ui_story_5022_50221301_4_dialog_content = "<color=#e8d9bb>Blam! Bang... Bang!</color>",
  ui_story_5022_50221301_5_dialog_content = "(We just ran over a small Eclipsite...)",
  ui_story_5022_50221301_6_dialog_content = "Won't this damage your front bumper and windshield?",
  ui_story_5022_50221301_7_dialog_content = "Don't you underestimate Bullock 8. He's not like those toys you see in Illumina.",
  ui_story_5022_50221301_8_dialog_content = "So stop worrying about my car. Take those binoculars and check on Zeta.",
  ui_story_5022_50221301_9_dialog_content = "Let me see...",
  ui_story_5022_50221301_10_dialog_content = "The... The dragon picked up her car, and Zeta's still inside!",
  ui_story_5022_50221301_11_dialog_content = "That doesn't sound good. We need to hurry up!",
  ui_story_5022_50221301_12_dialog_content = "Let's go.",
  ui_story_5022_50221301_13_dialog_content = "Okay! Wait... Azure, why are we going backwards?",
  ui_story_5022_50221301_14_dialog_content = "PlayerName, however much I'd love to confront this Eclipsite head-on...",
  ui_story_5022_50221301_15_dialog_content = "I've got a better plan.",
  ui_story_5022_50221301_16_dialog_content = "(Stay out of sight and climb up via small paths to a commanding point in the woods...)",
  ui_story_5022_50221301_17_dialog_content = "I see. This must be how snipers do it. You really know what you're doing.",
  ui_story_5022_50221301_18_dialog_content = "Couldn't have done it on my own. It'd take much longer if not for your ability to detect smaller Eclipsites along the way.",
  ui_story_5022_50221301_19_dialog_content = "... Is this what working as a team feels like? Not too shabby.",
  ui_story_5022_50221301_20_dialog_content = "Huh? What was that? Let me know if I can be of help!",
  ui_story_5022_50221301_21_dialog_content = "I was waiting for you to say that. PlayerName, come here and drop to your knees.",
  ui_story_5022_50221301_22_dialog_content = "Wait... Is that a gun? Why are you placing it on my...",
  ui_story_5022_50221301_23_dialog_content = "Keep it down!",
  ui_story_5022_50221301_24_dialog_content = "... Great. The height is just perfect.",
  ui_story_5022_50221301_25_dialog_content = "Stay still. Don't tremble.",
  ui_story_5022_50221301_26_dialog_content = "I'll try my best...",
  ui_story_5022_50221301_27_dialog_content = "Heh... Incredible.",
  ui_story_5022_50221301_28_dialog_content = "I dreamed about this moment thousands of times, but when I imagined it I never felt this...",
  ui_story_5022_50221301_29_dialog_content = "Calm.",
  ui_story_5022_50221301_30_dialog_content = "Can you see how Zeta is doing through your scope?",
  ui_story_5022_50221301_31_dialog_content = "Of course. She's hanging off the door, throwing bombs...",
  ui_story_5022_50221301_32_dialog_content = "While struggling to get back into the car.",
  ui_story_5022_50221301_33_dialog_content = "Why do I get the feeling that you're enjoying yourself watching this...",
  ui_story_5022_50221301_34_dialog_content = "Don't be stupid. We snipers begin our mission by observing our surroundings and predicting the target's movement.",
  ui_story_5022_50221301_35_dialog_content = "But you're right. I don't mind the show.",
  ui_story_5022_50221301_36_dialog_content = "Wind direction, checked. Wind speed, checked.",
  ui_story_5022_50221301_37_dialog_content = "Now we wait for the Eclipsite to turn around and give me its eye...",
  ui_story_5022_50221301_38_dialog_content = "Miss Azure, I've seen a similar High-Level Eclipsite before...",
  ui_story_5022_50221301_39_dialog_content = "We had to blow up an entire Illumina undercity to kill it.",
  ui_story_5022_50221301_40_dialog_content = "You don't trust me?",
  ui_story_5022_50221301_41_dialog_content = "... It's true that I failed to kill it before.",
  ui_story_5022_50221301_42_dialog_content = "Its claws are sharp and its skin indestructible.",
  ui_story_5022_50221301_43_dialog_content = "My friends and I shed blood and suffered because of it.",
  ui_story_5022_50221301_44_dialog_content = "But the past is the past... The Rediesel Wrench fears nothing.",
  ui_story_5022_50221301_45_dialog_content = "We never turn down a fight, and we always fight to win.",
  ui_story_5022_50221301_46_dialog_content = "If we can't win, we find an opportunity to get even.",
  ui_story_5022_50221301_47_dialog_content = "... And that opportunity is now!",
  ui_story_5022_50221301_48_dialog_content = "Boom!!",
  ui_story_5022_50221301_49_dialog_content = "!!!",
  ui_story_5022_50221301_50_dialog_content = "Did it work? I saw the bullet penetrate its eye...",
  ui_story_5022_50221301_51_dialog_content = "Don't move.",
  ui_story_5022_50221301_52_dialog_content = "O-Okay...",
  ui_story_5022_50221301_53_dialog_content = "... It didn't work.",
  ui_story_5022_50221301_54_dialog_content = "The target's behavior has changed, but it's still moving.",
  ui_story_5022_50221301_55_dialog_content = "However, though I don't know as much about Eclipsites as Roy...",
  ui_story_5022_50221301_56_dialog_content = "I think losing its eyes would count as a bad day for any living thing.",
  ui_story_5022_50221301_57_dialog_content = "Heh. Still moving despite having a bullet in its head... But that just makes it more interesting.",
  ui_story_5022_50221301_58_dialog_content = "<color=#e8d9bb>Bam! Boom, boom!</color>",
  ui_story_5022_50221301_59_dialog_content = "Woah, that blinding flash... And a string of explosions... Was that Zeta?",
  ui_story_5022_50221301_60_dialog_content = "Yeah. She got away.",
  ui_story_5022_50221301_61_dialog_content = "What do we do now? Reload the gun?",
  ui_story_5022_50221301_62_dialog_content = "I can feel other Eclipsites. They're drawn here by the gunshots and explosions...",
  ui_story_5022_50221301_63_dialog_content = "Let's go, PlayerName.",
  ui_story_5022_50221301_64_dialog_content = "Let's get that noisy little thing out of there first.",
  ui_story_5022_50221402_1_dialog_content = "Guaaahh!",
  ui_story_5022_50221402_2_dialog_content = "How come there are still so many Eclipsites... Are they coming from underground?",
  ui_story_5022_50221402_3_dialog_content = "They might have a lair somewhere in this canyon.",
  ui_story_5022_50221402_4_dialog_content = "That's an important piece of intelligence. However, right now we need to focus on the enemy.",
  ui_story_5022_50221402_5_dialog_content = "Good thing it's just running around madly after losing its eyes. Otherwise, we'd never be able to join up with Zeta.",
  ui_story_5022_50221402_6_dialog_content = "*Sobs*... Azure...",
  ui_story_5022_50221402_7_dialog_content = "Zeta, it's fine to hug the person who saved your life.",
  ui_story_5022_50221402_8_dialog_content = "But it's not nice to leave your snot all over her.",
  ui_story_5022_50221402_9_dialog_content = "The, the Caelestite then... Waaah...",
  ui_story_5022_50221402_10_option_content = "It's alright to wipe snot on me?!",
  ui_story_5022_50221402_11_dialog_content = "Just a little longer!",
  ui_story_5022_50221402_12_dialog_content = "I'm, I'm the heroine who'll save Astra. *Sniff* I can't give up just yet!",
  ui_story_5022_50221402_13_option_content = "Don't be afraid. We're here with you.",
  ui_story_5022_50221402_14_dialog_content = "*Sob*",
  ui_story_5022_50221402_15_dialog_content = "Thank you, Caelestite...",
  ui_story_5022_50221402_16_dialog_content = "I'm okay now.",
  ui_story_5022_50221402_17_dialog_content = "The Wicked Dragon Hakudoma showed up in the middle of my showdown with Azure... This is how fate tests the chosen one...",
  ui_story_5022_50221402_18_dialog_content = "(She's still sobbing, but she seems to be recovering pretty fast...)",
  ui_story_5022_50221402_19_dialog_content = "We need to wear it down. PlayerName, plan a route.",
  ui_story_5022_50221402_20_dialog_content = "Okay. I got this.",
  ui_story_5022_50221402_21_dialog_content = "<color=#e8d9bb>Bang... Bang... Bang...</color>",
  ui_story_5022_50221402_22_dialog_content = "<color=#e8d9bb>Boom... Boom... Boom...</color>",
  ui_story_5022_50221402_23_dialog_content = "Boom!!",
  ui_story_5022_50221402_24_dialog_content = "(In the previous operations, she followed the route I laid out for us, but...)",
  ui_story_5022_50221402_25_dialog_content = "(Now, Zeta has quickly figured out the pattern and is throwing candy bombs at spots hard for the wicked dragon to dodge...)",
  ui_story_5022_50221402_26_dialog_content = "(And Miss Azure is shooting each and every of those bombs... Their teamwork is simply perfect.)",
  ui_story_5022_50221402_27_dialog_content = "(This Eclipsite is different from any I've ever encountered.)",
  ui_story_5022_50221402_28_dialog_content = "Hmm... If it's similar to Nozard, it should be able to manipulate other Eclipsites to attack.",
  ui_story_5022_50221402_29_dialog_content = "But on the other hand, it looks and moves just like the ones Vice and I dealt with in the Whispering Corridor.",
  ui_story_5022_50221402_30_dialog_content = "Except it's tougher and thicker skinned. It's... It's almost indestructible.",
  ui_story_5022_50221402_31_dialog_content = "If we can't foresee how it'll act and pick its targets, this can get very dangerous...",
  ui_story_5022_50221402_32_dialog_content = "PlayerName, do you have a plan?",
  ui_story_5022_50221402_33_dialog_content = "... It looks like it's following a pattern when it's dodging our attacks... Like...",
  ui_story_5022_50221402_34_dialog_content = "<color=#e8d9bb>Boom...</color>",
  ui_story_5022_50221402_35_dialog_content = "Stop spacing out, Caelestite! The wicked dragon's claws are not for decoration!",
  ui_story_5022_50221402_36_dialog_content = "It's alright! I'll keep an eye on the Caelestite.",
  ui_story_5022_50221402_37_dialog_content = "... I got it!",
  ui_story_5022_50221402_38_dialog_content = "You scared me! What did you find out?",
  ui_story_5022_50221402_39_dialog_content = "That red core.",
  ui_story_5022_50221402_40_dialog_content = "Azure, did you notice it as well? Yes, it's protecting the core on its chest!",
  ui_story_5022_50221402_41_dialog_content = "Yes, I just confirmed it with my last shot.",
  ui_story_5022_50221402_42_dialog_content = "Since it lost its eyes, it's been relying on its instincts and an ability to sense Lumina to avoid our blows.",
  ui_story_5022_50221402_43_dialog_content = "Now that we've got its weak point... PlayerName! Zeta!",
  ui_story_5022_50221402_44_dialog_content = "Let's grind it to dust!",
  ui_story_5022_50221501_1_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5022_50221501_2_dialog_content = "Graaoooooohhh!",
  ui_story_5022_50221501_3_dialog_content = "Although we know its weak spot, the core seems to be very well protected. It's all but impossible to break.",
  ui_story_5022_50221501_4_dialog_content = "Miss Azure's bullet didn't get through... What should we do?",
  ui_story_5022_50221501_5_dialog_content = "Well... If one bullet doesn't work, we'll try ten. If that still doesn't work, we'll fire a hundred of them, all at the same spot.",
  ui_story_5022_50221501_6_dialog_content = "It wouldn't be very satisfying if we defeated it right away anyways.",
  ui_story_5022_50221501_7_dialog_content = "It... It's trying to escape!",
  ui_story_5022_50221501_8_dialog_content = "Don't even think about it!",
  ui_story_5022_50221501_9_dialog_content = "Our attacks have injured the wicked dragon's wings. It won't be able to fly.",
  ui_story_5022_50221501_10_dialog_content = "We'll need more firepower to further limit its movement...",
  ui_story_5022_50221501_11_dialog_content = "Eat lead!",
  ui_story_5022_50221501_12_dialog_content = "Azure, over here! I'll create openings for you.",
  ui_story_5022_50221501_13_dialog_content = "It's Jona and the others! How did they get so high up? Wow, what an entrance!",
  ui_story_5022_50221501_14_dialog_content = "PlayerName, follow me. Let's meet up with them.",
  ui_story_5022_50221501_15_dialog_content = "Ha, this'll be my greatest performance yet!",
  ui_story_5022_50221501_16_dialog_content = "No way! The last song is mine!",
  ui_story_5022_50221501_17_dialog_content = "Hah! My music will have turned the enemy to dust before you can even clear your throat!",
  ui_story_5022_50221501_18_dialog_content = "Alright, you two, the stage is all yours!",
  ui_story_5022_50221501_19_dialog_content = "But I have to say, you two are really fast. Lepidoz and others aren't even here yet.",
  ui_story_5022_50221501_20_dialog_content = "You know how lazy our lizard is. And it grows an attitude on long-distance trips.",
  ui_story_5022_50221501_21_dialog_content = "Roy knows how to coax it. They should get here soon.",
  ui_story_5022_50221501_22_dialog_content = "Well, then they'll miss all the dragon slaying fun. Now that I'm here we'll be done in seconds!",
  ui_story_5022_50221501_23_dialog_content = "Hmph. If you can keep up with me, that is!",
  ui_story_5022_50221501_24_dialog_content = "A warrior won't allow evil to escape! Now, count your sins!",
  ui_story_5022_50221501_25_dialog_content = "Even if it wanted to count its sins, I think we'd only hear \"gaah\" and \"garr.\"",
  ui_story_5022_50221501_26_dialog_content = "It's getting hot here! If you don't mind, I'll lay down a beat with my gun.",
  ui_story_5022_50221501_27_dialog_content = "Sigh...",
  ui_story_5022_50221501_28_dialog_content = "Now that everyone's here, I can't help but feel that it was a little stupid of me to try and take on the dragon alone.",
  ui_story_5022_50221501_29_dialog_content = "Gah...",
  ui_story_5022_50221501_30_dialog_content = "This time, I... I mean we...",
  ui_story_5022_50221501_31_dialog_content = "Won't let you escape alive!",
  ui_story_5022_50221502_1_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5022_50221502_2_dialog_content = "<size=45>Graaaaahhhhhh!</size>",
  ui_story_5022_50221502_3_dialog_content = "It's over.",
  ui_story_5022_50221502_4_dialog_content = "Did we win? I've used all of my candy bombs but they didn't seem to do much...",
  ui_story_5022_50221502_5_dialog_content = "Phew... Not bad, Azure. Visit the Squirming Sandworm when you find the time. It's on me.",
  ui_story_5022_50221502_6_dialog_content = "Looks like there won't be an encore. The big one turned into ashes as soon as it died.",
  ui_story_5022_50221502_7_dialog_content = "For a spectacular show like this, I don't mind being in the audience for once.",
  ui_story_5022_50221502_8_dialog_content = "They should strap both you and your screeching voice to the seats for good.",
  ui_story_5022_50221502_9_dialog_content = "What did you say to me? It was too windy to hear.",
  ui_story_5022_50221502_10_dialog_content = "(They fight and argue but deep down they're really close.)",
  ui_story_5022_50221502_11_dialog_content = "(I wonder what Vice is up to now...)",
  ui_story_5022_50221502_12_dialog_content = "(Wait... I feel like we're missing something really important again...)",
  ui_story_5022_50221502_13_dialog_content = "<color=#e8d9bb>Bang, bang, bang...</color>",
  ui_story_5022_50221502_14_dialog_content = "Something is approaching... A car?",
  ui_story_5022_50221502_15_dialog_content = "Hey! What's everyone hanging out here for?",
  ui_story_5022_50221502_16_dialog_content = "That car is making some concerning noises... But at least it's moving.",
  ui_story_5022_50221502_17_dialog_content = "Hey, everybody!",
  ui_story_5022_50221502_18_dialog_content = "Huh? Did we miss a party or something?",
  ui_story_5022_50221502_19_dialog_content = "Sigh... Brock wanted to help me fix the car, but he broke the Communicator. We haven't received anything since...",
  ui_story_5022_50221502_20_dialog_content = "I handed you exactly the screwdrivers you asked for!",
  ui_story_5022_50221502_21_dialog_content = "And I can tell you're very proud of it...",
  ui_story_5022_50221502_22_dialog_content = "Anyway... You won't beat me this time, Zeta!",
  ui_story_5022_50221502_23_dialog_content = "...",
  ui_story_5022_50221502_24_dialog_content = "I forgot that the race is still on!",
  ui_story_5022_50221502_25_dialog_content = "Absolute Zero Witch Azure!",
  ui_story_5022_50221502_26_dialog_content = "No need to yell, warrior.",
  ui_story_5022_50221502_27_dialog_content = "You beat the dragon before I could, but the rally isn't over yet!",
  ui_story_5022_50221502_28_dialog_content = "I... I won't wait for you to catch up!",
  ui_story_5022_50221502_29_dialog_content = "<color=#e8d9bb>Boom... Boom! Boom...</color>",
  ui_story_5022_50221502_30_dialog_content = "Zeta's car somehow survived the wicked dragon's claws...",
  ui_story_5022_50221502_31_dialog_content = "We don't have time to stand around and gape, PlayerName.",
  ui_story_5022_50221502_32_dialog_content = "Miss Azure?",
  ui_story_5022_50221502_33_dialog_content = "Would you join me for the rest of the race, and drive with me to the end of the world?",
  ui_story_5022_50221502_34_dialog_content = "Of course...",
  ui_story_5022_50221502_35_dialog_content = "But why are you making it sound weird?",
  ui_story_5022_50221502_36_dialog_content = "Dear listeners, just as I commented earlier during this exciting battle...",
  ui_story_5022_50221502_37_dialog_content = "Gah!!!",
  ui_story_5022_50221502_38_dialog_content = "(I almost forgot about this super loud radio commentator...)",
  ui_story_5022_50221502_39_dialog_content = "Team Azure and Team Zeta put aside old grudges and joined forces with our event staff.",
  ui_story_5022_50221502_40_dialog_content = "In an amazing show of skill, they defeated the Wicked Dragon Hakudoma!",
  ui_story_5022_50221502_41_dialog_content = "Unarmed members of Logistics Team 3 hid in a corner and broadcast the whole battle.",
  ui_story_5022_50221502_42_dialog_content = "There were no casualties other than the dragon, which was bombed into oblivion. Congratulations, everyone!",
  ui_story_5022_50221502_43_dialog_content = "I bet our contestants wish they could've heard my passionate commentary during the battle!",
  ui_story_5022_50221502_44_dialog_content = "(Err... Not really...)",
  ui_story_5022_50221502_45_dialog_content = "But don't worry. I hear your call!",
  ui_story_5022_50221502_46_dialog_content = "I'll retell the whole story especially for you at the celebration feast later!",
  ui_story_5022_50221502_47_dialog_content = "I'll retell it with such realism and detail, it'll be better than joining the actual battle. And for 1,000 Nightium only!",
  ui_story_5022_50221502_48_dialog_content = "Now, our contestants are back in the competition, racing towards the finishing line at the boundary of Eternal Night!",
  ui_story_5022_50221502_49_dialog_content = "What's more, Lepidoz has finally broken free from the crevice and is heading in the same direction!",
  ui_story_5022_50221502_49X_dialog_content = "It really needs to watch what it eats...",
  ui_story_5022_50221502_50_dialog_content = "The race is entering its final stage. What other surprises do our contestants have for us?",
  ui_story_5022_50221502_51_dialog_content = "Azure, look! Up ahead!",
  ui_story_5022_50221502_52_dialog_content = "... Zeta! <size=45>You won't get away this time! </size><size=40>... You... </size><size=35>... Ah... </size><size=30>... Ow... </size><size=25>... Ouch... </size><size=20>...</size>",
  ui_story_5022_50221502_53_dialog_content = "Er... Sounds like Brock's car is rolling down the hill...",
  ui_story_5022_50221502_54_dialog_content = "On the zigzagging downhill section of the Blazing Tooth, Sweet Devil and My Super Dream Team are having a fierce battle!",
  ui_story_5022_50221502_55_dialog_content = "Zeta seemed to veer left during the right turn, but she was actually positioning herself for the left turn right after!",
  ui_story_5022_50221502_56_dialog_content = "The result was an absolutely perfect drift!",
  ui_story_5022_50221502_57_dialog_content = "Fooled by her excellent techniques, Powerball of My Super Dream Team has driven off the road! Looks like it'll be in need of some serious repair work.",
  ui_story_5022_50221502_58_dialog_content = "Meanwhile, Azure is quickly catching up...",
  ui_story_5022_50221502_59_dialog_content = "Her car's windshield is shattered... Is it really safe to drive like that?",
  ui_story_5022_50221502_60_dialog_content = "Careful now! This is Sand Dragon, the Rainbow Chaser you're talking about!",
  ui_story_5022_50221502_61_dialog_content = "What a name!",
  ui_story_5022_50221502_62_dialog_content = "You're actually keeping up. The legend lives up to her reputation...",
  ui_story_5022_50221502_63_dialog_content = "Let's see how you handle this!",
  ui_story_5022_50221502_64_dialog_content = "Whoa, she's speeding up!",
  ui_story_5022_50221502_65_dialog_content = "You move too much when you shift gears.",
  ui_story_5022_50221502_66_dialog_content = "Wha... what?",
  ui_story_5022_50221502_67_dialog_content = "Listen. Don't get distracted by others or by any advantages or disadvantages you may have. Focus on yourself.",
  ui_story_5022_50221502_68_dialog_content = "(I can't see anything outside but I think they're side by side!)",
  ui_story_5022_50221502_69_dialog_content = "What do you know? It's not like you beat me before...",
  ui_story_5022_50221502_70_dialog_content = "Hah. I was a two-time champion of the Blazing Tooth Circuit before you were even born.",
  ui_story_5022_50221502_71_dialog_content = "I can tell exactly what stupid tricks you're planning to pull just by listening to the radio commentary...",
  ui_story_5022_50221502_72_dialog_content = "... And I know how you plan to win the race.",
  ui_story_5022_50221502_73_dialog_content = "You... You've been watching me?",
  ui_story_5022_50221502_74_dialog_content = "Azure!",
  ui_story_5022_50221502_75_dialog_content = "Huh? Don't like what I said? Well, prove me wrong.",
  ui_story_5022_50221502_76_dialog_content = "I thought the most important thing in this race was to beat you...",
  ui_story_5022_50221502_77_dialog_content = "But how come...",
  ui_story_5022_50221502_78_dialog_content = "Even though I didn't beat you yet...",
  ui_story_5022_50221502_79_dialog_content = "I feel... happy?",
  ui_story_5022_50221502_80_dialog_content = "Hmm?",
  ui_story_5022_50221502_81_dialog_content = "This circuit... This record attempt... This...",
  ui_story_5022_50221502_82_dialog_content = "I've never done this well before.",
  ui_story_5022_50221502_83_dialog_content = "*sobs*... Waaaah!",
  ui_story_5022_50221502_84_dialog_content = "Why is she crying again?! Good thing there's nothing but sand plains ahead...",
  ui_story_5022_50221502_85_dialog_content = "Heh, that brings back memories. I used to be like that myself.",
  ui_story_5022_50221502_86_dialog_content = "Then I realized that winning was less rewarding than working with my rivals to push our limits.",
  ui_story_5022_50221502_87_dialog_content = "I have to admit, you're a pretty decent driver.",
  ui_story_5022_50221502_88_dialog_content = "Azure...",
  ui_story_5022_50221502_89_dialog_content = "However, that doesn't mean I'm going to let you win!",
  ui_story_5022_50221502_90_dialog_content = "I'm going to set a new record for the Blazing Tooth.",
  ui_story_5022_50221502_91_dialog_content = "D-Don't be too sure about that!",
  ui_story_5022_50221502_92_dialog_content = "Don't forget to share the candies you keep under your bed and apologize to everyone when you lose!",
  ui_story_5022_50221502_93_dialog_content = "Forget you ever heard that! You witch!",
  ui_story_5022_50221502_94_dialog_content = "Aww, but how could I forget the final request of a warrior?",
  ui_story_5022_50221502_95_dialog_content = "Aaah! I'm not going to lose this one! If I beat you, you'll have to take me on your missions from now on!",
  ui_story_5022_50221502_96_dialog_content = "(Even I'm getting excited watching this exchange...)",
  ui_story_5022_50221502_97_dialog_content = "(Is this what Sinsa calls the real race? I think I'm starting to get what he meant.)",
  ui_story_5022_50221502_98_dialog_content = "(Wait... Did something just fly past overhead?)",
  ui_story_5022_50221502_99_dialog_content = "Eh...",
  ui_story_5022_50221502_100_dialog_content = "Eh?!?!",
  ui_story_5022_50221601_1_dialog_content = "ZzZzz... Oh!",
  ui_story_5022_50221601_2_dialog_content = "I have to stay awake to see the drivers cross the finish line...",
  ui_story_5022_50221601_3_dialog_content = "You can lean on my shoulder if you want to sleep. And don't worry about the race.",
  ui_story_5022_50221601_4_dialog_content = "I may not be able to see, but I'll feel the wind when the cars approach.",
  ui_story_5022_50221601_5_dialog_content = "Dawn, is there still no sign of them? It's so hot here, it's making me sleepy...",
  ui_story_5022_50221601_6_dialog_content = "I can feel a vibration in the distance...",
  ui_story_5022_50221601_7_dialog_content = "No, hold on... Something massive is coming...",
  ui_story_5022_50221601_8_dialog_content = "From the sky.",
  ui_story_5022_50221601_9_dialog_content = "Ohh! It's coming!",
  ui_story_5022_50221601_10_dialog_content = "This... Could it be...?",
  ui_story_5022_50221601_11_dialog_content = "Huh... This is the rainbow ribbon at the finish line. Why is it here? Did someone finish the race?",
  ui_story_5022_50221601_12_dialog_content = "That vehicle is enormous.... I don't remember seeing anything like that at the starting line.",
  ui_story_5022_50221601_13_dialog_content = "Ah... It's PlayerName's Soroz!",
  ui_story_5022_50221601_14_dialog_content = "Now that you mention it... Odi did send a message saying that a Colossus handed in an entry form at the checkpoint in the Hot Air Desert...",
  ui_story_5022_50221601_15_dialog_content = "I thought she was joking.",
  ui_story_5022_50221601_16_dialog_content = "I hereby announce that the winner of the Blazing Rally is...",
  ui_story_5022_50221601_17_dialog_content = "<size=45>Soroz and its pilot!</size>",
  ui_story_5022_50221601_18_dialog_content = "Now, finally, we'll proceed to the highly anticipated award ceremony!",
  ui_story_5022_50221601_19_dialog_content = "The rally champion can make a wish to Eve!",
  ui_story_5022_50221601_20_dialog_content = "The champion, Miss Vice, wishes for... a gift pack of ways to teach Sinsa a lesson!",
  ui_story_5022_50221601_21_dialog_content = "What now?",
  ui_story_5022_50221601_22_dialog_content = "Let's hear Miss Vice's acceptance speech!",
  ui_story_5022_50221601_23_dialog_content = "Don't leave behind a note that reads, \"I have PlayerName. Come to the Hot Air Desert if you want to see him again...\"",
  ui_story_5022_50221601_24_dialog_content = "And then take him!",
  ui_story_5022_50221601_25_dialog_content = "That's called kidnapping!",
  ui_story_5022_50221601_26_dialog_content = "After the acceptance speech, it's time for our champion Miss Vice to receive her reward!",
  ui_story_5022_50221601_27_dialog_content = "So, I guess that means I'll have to teach my brother a lesson?",
  ui_story_5022_50221601_28_dialog_content = "No, Eve, please...",
  ui_story_5022_50221601_29_dialog_content = "Aaaaaaaargh!!",
  ui_story_5022_50221601_30_dialog_content = "Woah, I did not see that coming.",
  ui_story_5022_50221601_31_dialog_content = "*Sniffling* I can accept that we raced to a draw, but... Where did that Vice lady come from?",
  ui_story_5022_50221601_32_dialog_content = "She's lucky she's a friend of the Caelestite and that her tail is so cool...",
  ui_story_5022_50221601_33_dialog_content = "Otherwise, I'd have challenged her to a duel already!",
  ui_story_5022_50221601_34_dialog_content = "Azure, how come you're so calm? Aren't you disappointed?",
  ui_story_5022_50221601_35_dialog_content = "Well, she didn't cheat, did she? Very few people are able to fly a Colossus. I'd say she won fair and square.",
  ui_story_5022_50221601_36_dialog_content = "Besides, it's a treat watching you jump up and down like an angry little gerbil.",
  ui_story_5022_50221601_37_dialog_content = "What did you say to me?",
  ui_story_5022_50221601_38_dialog_content = "(I'd never thought that Vice would fly Soroz here...)",
  ui_story_5022_50221601_39_dialog_content = "PlayerName!",
  ui_story_5022_50221601_40_dialog_content = "How could you leave with Sinsa without telling me?",
  ui_story_5022_50221601_41_dialog_content = "I heard everything on the radio! Driving a racecar across a volcano... Fighting a nine-headed Eclipsite that looked like a dragon...",
  ui_story_5022_50221601_42_dialog_content = "The battle was already over when Soroz and I made it to the canyon. Do you have any idea how worried we were?",
  ui_story_5022_50221601_43_option_content = "I'm sorry. I really am!",
  ui_story_5022_50221601_44_dialog_content = "(She doesn't seem to remember our argument...)",
  ui_story_5022_50221601_45_option_content = "Please forgive me, Vice.",
  ui_story_5022_50221601_46_dialog_content = "I thought you were mad at me...",
  ui_story_5022_50221601_47_dialog_content = "I promise I'll always tell you where I'm going from now on.",
  ui_story_5022_50221601_48_dialog_content = "Hmm... Fine. I'll forgive you this once, but only because you seem to really regret it!",
  ui_story_5022_50221601_49_dialog_content = "And to be fair, the rally was fun and that volcano was pretty spectacular.",
  ui_story_5022_50221601_50_dialog_content = "Flying Soroz may have been bending the rules a little, but the only rule in the rally is that there are no rules. Right?",
  ui_story_5022_50221601_51_dialog_content = "You should invite me next year, I'm a pretty good hovercar driver!",
  ui_story_5022_50221601_52_dialog_content = "Vice...",
  ui_story_5022_50221601_53_dialog_content = "Perhaps we should play games together, it could help us perform better in the race.",
  ui_story_5022_50221601_54_dialog_content = "Vice!",
  ui_story_5022_50221601_55_dialog_content = "Oh, and PlayerName, don't forget your training program. I'll remind you every day as always!",
  ui_story_5022_50221601_56_dialog_content = "Err... I don't think that's...",
  ui_story_5022_50221601_57_dialog_content = "<color=#e8d9bb>Crackle...</color>",
  ui_story_5022_50221601_58_dialog_content = "Hey everyone! Did you miss me?!",
  ui_story_5022_50221601_59_dialog_content = "What was that?",
  ui_story_5022_50221601_60_dialog_content = "It's okay. It's just the radio. It gave me a start too when I first heard it.",
  ui_story_5022_50221601_61_dialog_content = "Jomu has been airing commercials this whole time. He didn't even mention that Soroz joined the race...",
  ui_story_5022_50221601_62_dialog_content = "I bet some of our listeners must be complaining that I haven't mentioned the appearance of Vice in the race!",
  ui_story_5022_50221601_63_dialog_content = "Indeed, this is the first time ever that a Colossus has joined the Blazing Rally!",
  ui_story_5022_50221601_64_dialog_content = "Cough... And in order to keep the race interesting, it may well be the last time as well.",
  ui_story_5022_50221601_65_dialog_content = "I only held off on mentioning it in order to create a bit of suspense for our listeners!",
  ui_story_5022_50221601_66_dialog_content = "Thank you for turning in to our program for this year's Blazing Rally. See you next time, and don't forget to fill out the survey!",
  ui_story_5022_50221601_67_dialog_content = "Also, please drop by my store. We've got...",
  ui_story_5022_50221601_68_dialog_content = "Hey, Jomu! Come here. I have a whole basin of dates for you to peel.",
  ui_story_5022_50221601_69_dialog_content = "Roy, I'm broadcasting!",
  ui_story_5022_50221601_70_dialog_content = "Great. Then tell everyone to stop playing and come over, food's ready.",
  ui_story_5022_50221601_71_dialog_content = "Brock, don't open those cans of protein powder. Didn't I tell you... Hey, no, don't pour it into your mouth! Fleur, stop him!",
  ui_story_5022_50221601_72_dialog_content = "Cough... So, I guess you all heard...",
  ui_story_5022_50221601_73_dialog_content = "It's time for the celebration feast!",
  ui_story_5022_50221601_74_dialog_content = "All right, I'll finish dealing with my brother after the food.",
  ui_story_5022_50221601_75_dialog_content = "There's more?!",
  ui_story_5022_50221601_76_dialog_content = "How is it? Much better than before, right?",
  ui_story_5022_50221601_77_dialog_content = "It's edible. Usually, the only thing that's actually worth looking forward to is the dessert. What are we getting today?",
  ui_story_5022_50221601_78_dialog_content = "Sea Buckthorn Pudding, your favorite!",
  ui_story_5022_50221601_79_dialog_content = "With date puree? I like it thick and rich!",
  ui_story_5022_50221601_80_dialog_content = "Well, that depends on whether Jomu is done peeling them yet.",
  ui_story_5022_50221601_81_dialog_content = "What do think, PlayerName? It was a pretty good ride, wasn't it?",
  ui_story_5022_50221601_82_dialog_content = "It definitely exceeded my expectations. Wait, what... What did you just feed me?!",
  ui_story_5022_50221601_83_dialog_content = "Try it. Lizard skewer!",
  ui_story_5022_50221601_84_dialog_content = "Are you sure this is edible?",
  ui_story_5022_50221601_85_dialog_content = "Of course! Look at Azure!",
  ui_story_5022_50221601_86_dialog_content = "I can't believe Miss Azure is eating this... and in such an elegant way...",
  ui_story_5022_50221601_87_dialog_content = "This too, PlayerName. Want to have a taste?",
  ui_story_5022_50221601_88_dialog_content = "This is my favorite Baked Rattlesnake with Cheese!",
  ui_story_5022_50221601_89_dialog_content = "Err... Thank you but...",
  ui_story_5022_50221601_90_dialog_content = "Eat up! Don't be shy.",
  ui_story_5022_50221601_91_dialog_content = "I'm not really... I... Oh...",
  ui_story_5022_50221601_92_dialog_content = "These are just the appetizers. We haven't even gotten to the main entrees yet.",
  ui_story_5022_50221601_93_dialog_content = "Have you been moved to tears by all these foods you've never had the fortune of trying before? Poor thing...",
  ui_story_5022_50221601_94_dialog_content = "Over here. I have Lizard Egg Stew with Beetles!",
  ui_story_5022_50221601_95_dialog_content = "Hmm! Roasted marshmallow is so tasty! We must make this back home as well!",
  ui_story_5022_50221601_96_dialog_content = "Vice, you've had enough. Come and help me...",
  ui_story_5022_50221601_97_dialog_content = "Azure?",
  ui_story_5022_50221601_98_dialog_content = "What are you doing sitting here all by yourself? The dessert won't wait for anyone.",
  ui_story_5022_50221601_99_dialog_content = "Did you manage to grab some?",
  ui_story_5022_50221601_100_dialog_content = "Of course. I also stole Zeta's portion because she's too busy showing off her prize doll.",
  ui_story_5022_50221601_101_dialog_content = "You used to leave right after the rally and never attended a celebration feast. Now you know what you've missed all these years!",
  ui_story_5022_50221601_102_dialog_content = "Huh. Don't push it.",
  ui_story_5022_50221601_103_dialog_content = "Hahaha, we never used to be able to indulge in lavish meals and desserts like this. No more relying on roasted lizards to fill our stomachs!",
  ui_story_5022_50221601_104_dialog_content = "I believe I deserve to push it a little.",
  ui_story_5022_50221601_105_dialog_content = "You still have a habit of reminiscing about the past like an old geezer. Don't come running to me when the youngsters start getting annoyed by you.",
  ui_story_5022_50221601_106_dialog_content = "Wow, that's cold! Please, I'm still in the prime of my life.",
  ui_story_5022_50221601_107_dialog_content = "...",
  ui_story_5022_50221601_108_dialog_content = "... Azure.",
  ui_story_5022_50221601_109_dialog_content = "Do you think his wish has been fulfilled?",
  ui_story_5022_50221601_110_dialog_content = "Why are you suddenly asking? Besides, nobody knew the former leader better than you.",
  ui_story_5022_50221601_111_dialog_content = "Just answer me, please.",
  ui_story_5022_50221601_112_dialog_content = "...",
  ui_story_5022_50221601_113_dialog_content = "Alright, let me think.",
  ui_story_5022_50221601_114_dialog_content = "Our protection fee collection and scavenging operation is running smoothly. We're doing pretty well when it comes to blows with our enemies and within our gang...",
  ui_story_5022_50221601_115_dialog_content = "Everyone is enjoying the pleasures of life and surprisingly we're all well fed and warmly dressed.",
  ui_story_5022_50221601_116_dialog_content = "For a ragtag group of people who'd been left behind or abandoned that decided to band together, I'll say we've done a pretty good job.",
  ui_story_5022_50221601_117_dialog_content = "For many of us -including me- this is already the closest thing to home after all that we have lost.",
  ui_story_5022_50221601_118_dialog_content = "Like weeds, we were once uprooted but on a barren land we took root and grew beyond control.",
  ui_story_5022_50221601_119_dialog_content = "From our place in the desert, we put out fires the high and mighty noble lords can't, and we settle the matters that fall beyond their reach.",
  ui_story_5022_50221601_120_dialog_content = "So I would say yes.",
  ui_story_5022_50221601_121_dialog_content = "... Thank you.",
  ui_story_5022_50221601_122_dialog_content = "Although comparing us to weeds... Well, I guess you have a point.",
  ui_story_5022_50221601_123_dialog_content = "Go find young Sinsa if you want to hear someone wax poetics, that's not my thing.",
  ui_story_5022_50221601_124_dialog_content = "You're still calling him that? He might be younger than us, but he's already a capable leader in his own right.",
  ui_story_5022_50221601_125_dialog_content = "Seriously? Our capable leader was just whining to PlayerName by the campfire.",
  ui_story_5022_50221601_126_dialog_content = "He was complaining how you still pat him on the head and embarrass him by exposing all the silly mistakes back when he was just a young green grasshopper.",
  ui_story_5022_50221601_127_dialog_content = "Heh. All in all, young Sinsa isn't all that reliable yet. At least his acting skills still have a lot of room for improvement.",
  ui_story_5022_50221601_128_dialog_content = "You made him follow me, didn't you? Zeta challenged me, and Sinsa and PlayerName got in my car...",
  ui_story_5022_50221601_129_dialog_content = "Don't tell me even the appearance of the Colossus was in your calculations?",
  ui_story_5022_50221601_130_dialog_content = "Hey, you know I'm not that bright.",
  ui_story_5022_50221601_131_dialog_content = "The only thing I really planned for was for you to have some companions this year for once.",
  ui_story_5022_50221601_132_dialog_content = "I wanted to show you how much those little ones and the entire Rediesel Wrench have grown since you went off on your own.",
  ui_story_5022_50221601_133_dialog_content = "Then one thing led to another...",
  ui_story_5022_50221601_134_dialog_content = "I was so anxious I nearly threw up when you and the Caelestite flew off the volcano...",
  ui_story_5022_50221601_135_dialog_content = "Hmm? How strange to hear this from the man who taught me to use Eclipsites as a cushion, and sand slopes as an acceleration belt, and keep my speed at downhill curves!",
  ui_story_5022_50221601_136_dialog_content = "Ahaha. True...",
  ui_story_5022_50221601_137_dialog_content = "That dragon was a total surprise.",
  ui_story_5022_50221601_138_dialog_content = "I wish the wicked dragon could remain in stories only for Zeta.",
  ui_story_5022_50221601_139_dialog_content = "Although new experiences help us grow. Injuries are just a part of training, and a rite of passage for Rediesel Wrench members.",
  ui_story_5022_50221601_140_dialog_content = "But she came back safe and sound... Hold on. Could Zeta really be the chosen heroine?",
  ui_story_5022_50221601_141_dialog_content = "In adventure tales, the protagonist's parents always die in the beginning, which says a lot about my fate.",
  ui_story_5022_50221601_142_dialog_content = "Ouch!",
  ui_story_5022_50221601_143_dialog_content = "That's not funny. Zeta would cry, and she's noisy when she does. I've already suffered through it twice today.",
  ui_story_5022_50221601_144_dialog_content = "When did you two get so close? Not bad... How about bringing her along on your next mission?",
  ui_story_5022_50221601_145_dialog_content = "Don't even think about it! She'll have to win against me at the Blazing Tooth first.",
  ui_story_5022_50221601_146_dialog_content = "So you're in for next year's rally?",
  ui_story_5022_50221601_147_dialog_content = "... Hmm. I guess.",
  ui_story_5022_50221601_148_dialog_content = "Excellent! The Exploration team's quests are important. But we all need to loosen up a little from time to time and live life to its fullest.",
  ui_story_5022_50221601_149_dialog_content = "You don't have to teach me that. I often...",
  ui_story_5022_50221601_150_dialog_content = "Meet up with Jona to drink up the local tavern's storage before driving to the next town to drink more? I really can't call that a healthy hobby.",
  ui_story_5022_50221601_151_dialog_content = "Um...",
  ui_story_5022_50221601_152_dialog_content = "It's a small improvement, but I'm glad you're back on the tracks.",
  ui_story_5022_50221601_153_dialog_content = "You've always liked to act tough...",
  ui_story_5022_50221601_154_dialog_content = "And where did I get that from? None other than you!",
  ui_story_5022_50221601_155_dialog_content = "... Huh? Is that so?",
  ui_story_5022_50221601_156_dialog_content = "You're the one who should be sitting back and letting the youngsters take the reign!",
  ui_story_5022_50221601_157_dialog_content = "<color=#e8d9bb>Bam... Boom!</color>",
  ui_story_5022_50221601_158_dialog_content = "...",
  ui_story_5022_50221601_159_dialog_content = "...",
  ui_story_5022_50221601_160_dialog_content = "Wahahaha! The sparklers blasted all over Regina's face! Look, hahaha!",
  ui_story_5022_50221601_161_dialog_content = "Brock, your face is also smudged.",
  ui_story_5022_50221601_162_dialog_content = "Barbara, I'm going to kill you!",
  ui_story_5022_50221601_163_dialog_content = "Woah! This bomb would be perfect on the stage. Don't you think, Tiny One?",
  ui_story_5022_50221601_164_dialog_content = "Yep, but we need to adjust the explosion radius. Let me see the interior structure...",
  ui_story_5022_50221601_165_dialog_content = "Do you like it, do you like it? I've got more from the same series! They've been improved!",
  ui_story_5022_50221601_166_dialog_content = "You just want to set off fireworks.",
  ui_story_5022_50221601_167_dialog_content = "Isn't that the perfect way to end the celebratory feast? Even Lepidoz is wagging its tail.",
  ui_story_5022_50221601_168_dialog_content = "What was it you were saying? \"Let the youngsters take the reins\" or something?",
  ui_story_5022_50221601_169_dialog_content = "Geez, these brats...",
  ui_story_5022_50221601_170_dialog_content = "Hahaha, it's not a bad thing for them to hold onto their youth.",
  ui_story_5022_50221601_171_dialog_content = "Cae-les-tite! Were you the one who ate my dessert?!",
  ui_story_5022_50221601_172_dialog_content = "Even if you saved my life, stealing someone's dessert can't be forgiven!",
  ui_story_5022_50221601_173_dialog_content = "It wasn't me! It was Miss Azure... She...",
  ui_story_5022_50221601_174_dialog_content = "Where did she go? Miss Azure!",
  ui_story_5022_50221601_175_dialog_content = "Oh my, looks like your little teammate is in trouble. Aren't you going to intervene?",
  ui_story_5022_50221601_176_dialog_content = "Don't underestimate PlayerName.",
  ui_story_5022_50221601_177_dialog_content = "There are interesting things yet to come for that one.",
  ui_story_5022_50221601_178_dialog_content = "The Caelestite's story won't be brought to an end by pudding.",
  ui_story_5022_50221601_179_dialog_content = "I believe in this.",
  ui_story_5022_50221601_180_dialog_content = "Yes, that was a great line you just said. But it doesn't change the fact that the Caelestite is being chased around because of you.",
  ui_story_5022_50221601_181_dialog_content = "Azure! Roy!",
  ui_story_5022_50221601_182_dialog_content = "Come here! It's time for fireworks!",
  ui_story_5022_50221601_183_dialog_content = "3——2——1——!"
}
return config
